/* GENERERAD av .claude/i18n/bygg-begrepp-sok.js ur data/en/begrepp/*.js. Redigera inte. */
I18N.innehall('begrepp', {"absoluta-nollpunkten":{"kalla":"da276bfc31","data":{"term":"Absolute zero","kort":"The lowest temperature that can exist at all: −273.15 °C, or 0 kelvin. There, the thermal motion of the particles has in principle stopped completely.","former":["absolute zero"]}},"absorptionskant":{"kalla":"f5098f7162","data":{"term":"Absorption edge","kort":"The energy at which an element suddenly starts to swallow radiation much more strongly than just below it. The edge lies in different places for different elements and works like a fingerprint.","former":["absorption edge","absorption edges"]}},"ackretionsskiva":{"kalla":"048565b6f3","data":{"term":"Accretion disc","kort":"A rotating disc of gas and dust on its way in towards a heavy central body: a young star, a white dwarf or a black hole. Friction in the disc heats the matter up so that it glows.","former":["accretion disc","accretion discs","accretion disk","accretion disks","accretion"]}},"aerogel":{"kalla":"bab7f49956","data":{"term":"Aerogel","kort":"A solid material that consists mostly of air, made by replacing the liquid in a gel with gas without the structure collapsing. It is among the lightest solids there are.","former":["aerogel","aerogels","silica aerogel","silica aerogels"]}},"aktinid":{"kalla":"fbf040bd7a","data":{"term":"Actinide","kort":"The fifteen elements from actinium to lawrencium, at the very bottom of the periodic table. All of them are radioactive, and the heaviest do not occur in nature but have to be made.","former":["actinide","actinides","actinoid","actinoids","fermium","einsteinium","californium","superheavy element","superheavy elements","transuranic element","transuranic elements","transuranium element","transuranium elements"]}},"akustisk-levitation":{"kalla":"dc99d0ddbd","data":{"term":"Acoustic levitation","kort":"Holding a small object floating freely in the air using very loud sound, usually ultrasound. The force arises because the sound pressure is different on different sides of the object.","former":["acoustic levitation","levitation","acoustic levitator","acoustic levitators","levitator","levitators"]}},"alfastralning":{"kalla":"113485cb72","data":{"term":"Alpha radiation","kort":"Radiation consisting of helium nuclei thrown out of heavy atomic nuclei. It is the most ionising kind of radiation but is stopped by a sheet of paper.","former":["alpha radiation","alpha decay","alpha decays","alpha particle","alpha particles","alpha emitter","alpha emitters"]}},"altermagnetism":{"kalla":"a182e85e21","data":{"term":"Altermagnetism","kort":"A third kind of magnetism, identified in the 2020s: the material is non-magnetic on the outside like an antiferromagnet, but the electrons behave as in a ferromagnet.","former":["altermagnetism","altermagnet","altermagnets","altermagnetic"]}},"angstrom":{"kalla":"c565fab885","data":{"term":"Ångström","kort":"A tenth of a nanometre, which is just the size of an atom. The unit is not part of the SI system but lives on in chemistry and crystallography precisely because the size fits so well.","former":["ångström","ångströms","angstrom","angstroms","ångström unit","angstrom unit"]}},"annihilation":{"kalla":"44574f27d0","data":{"term":"Annihilation","kort":"What happens when a particle meets its antiparticle: both disappear and their entire mass becomes energy. It is the most complete energy conversion known in nature.","former":["annihilation","annihilations","annihilate","annihilates","annihilated"]}},"antecyklon":{"kalla":"b6391e0671","data":{"term":"Anticyclone","kort":"A vortex in an atmosphere that rotates in the opposite direction to a low-pressure system. Around an anticyclone the air sinks downwards, and on Earth this usually means high pressure and clear weather.","former":["anticyclone","anticyclones","anticyclonic"]}},"antimateria":{"kalla":"b3dbdedec5","data":{"term":"Antimatter","kort":"The mirror image of matter: for every particle there is an antiparticle with the same mass but opposite charge. When they meet, both are destroyed and become pure energy.","former":["antimatter","antiparticle","antiparticles","antiproton","antiprotons","antihydrogen","antiatom","antiatoms"]}},"anyon":{"kalla":"35de6a8b9b","data":{"term":"Anyon","kort":"A kind of quasiparticle that can only exist in two dimensions and that behaves neither like an electron nor like a photon when two of them swap places.","former":["anyon","anyons","non-abelian anyon","non-abelian anyons"]}},"asteroid":{"kalla":"761fa7bad3","data":{"term":"Asteroid","kort":"A body of rock or metal orbiting the Sun, too small to be called a planet. Most of them are found in the asteroid belt between Mars and Jupiter.","former":["asteroid","asteroids","asteroid belt","near-earth asteroid","near-earth asteroids"]}},"astronomisk-enhet":{"kalla":"543022637e","data":{"term":"Astronomical unit","kort":"The distance between the Earth and the Sun, just under 150 million km. It is the yardstick astronomers use within the solar system, where light years are unreasonably large.","former":["astronomical unit","astronomical units"]}},"atominterferometri":{"kalla":"f60742bd6d","data":{"term":"Atom interferometry","kort":"A measurement method in which a cloud of atoms is treated as a wave: it is split into two parts that take different paths and are then recombined, and the resulting pattern reveals the smallest difference between the paths.","former":["atom interferometry","atom interferometer","atom interferometers","atomic interferometry"]}},"atomur":{"kalla":"18e5034f4c","data":{"term":"Atomic clock","kort":"A clock that keeps time using an atom instead of a pendulum or a quartz crystal. The gap between two of the atom's energy levels is exactly the same for every atom of the same kind, and you can count oscillations in that gap.","former":["atomic clock","atomic clocks","caesium clock","caesium clocks","cesium clock","cesium clocks","ion clock","ion clocks","aluminium ion clock","aluminum ion clock"]}},"attosekund":{"kalla":"2fd60d106b","data":{"term":"Attosecond","kort":"A billionth of a billionth of a second. It is the timescale on which electrons move inside an atom, and the shortest time that can be measured in a laboratory today.","former":["attosecond","attoseconds","attosecond pulse","attosecond pulses","attosecond physics"]}},"axionliknande-partikel":{"kalla":"2fd94ed2a6","data":{"term":"Axion-like particle","kort":"A hypothetical, extremely light particle that can change identity with a photon when it passes through a magnetic field. No one has found one yet, but they turn up in explanations of both dark matter and light that seems to have travelled too far.","former":["axion-like particle","axion-like particles","axionlike particle","axionlike particles","axion","axions"]}},"axiparabola":{"kalla":"71f6979aab","data":{"term":"Axiparabola","kort":"A mirror ground so that different parts of its surface have different focal lengths. Instead of collecting the light in a single point, it stretches the focus out into a long, narrow line.","former":["axiparabola","axiparabolas","axiparabolae","axiparabolic mirror","axiparabolic mirrors"]}},"bagsekund":{"kalla":"441bdacba0","data":{"term":"Arcsecond","kort":"A unit for very small angles: one arcsecond is 1/3600 of a degree. Astronomers give positions and apparent sizes in the sky in arcminutes, arcseconds and thousandths of an arcsecond.","former":["arcsecond","arcseconds","arc second","arc seconds","arcminute","arcminutes","arc minute","arc minutes","milliarcsecond","milliarcseconds"]}},"ballistiska-fotoner":{"kalla":"5692f6b171","data":{"term":"Ballistic photons","kort":"The particles of light that get straight through a cloudy material without bouncing off anything on the way. They are few, but they are the only ones that carry a sharp image of what was behind.","former":["ballistic photons","ballistic photon","ballistic light","ballistic"]}},"bandgap":{"kalla":"23dfda9196","data":{"term":"Band gap","kort":"The energy jump an electron in a solid has to make to get free of its bond and be able to conduct electricity. The width of the gap decides whether the material is a metal, a semiconductor or an insulator.","former":["band gap","band gaps","bandgap","bandgaps","energy gap","energy gaps","valence band","valence bands","conduction band","conduction bands"]}},"baryon":{"kalla":"53312a046b","data":{"term":"Baryon","kort":"The collective name for particles built from three quarks; the proton and the neutron are the two common ones. Every baryon is given the baryon number 1, a bookkeeping number that has never been observed to change.","former":["baryon","baryons","baryon number","baryon numbers","antibaryon","antibaryons","valence quark","valence quarks"]}},"baryonknut":{"kalla":"c3df2f59ec","data":{"term":"Baryon junction","kort":"A Y-shaped point inside a proton or neutron where the three force fields from the quarks meet. According to a debated idea, it is the junction, not the quarks, that carries the particle's baryon number.","former":["baryon junction","baryon junctions","gluon junction","gluon junctions","gluon string","gluon strings","baryon knot"]}},"bells-olikhet":{"kalla":"e77860ed17","data":{"term":"Bell's inequality","kort":"A limit on how strongly two measurement results can be connected if the particles carry ready-made, hidden answers with them. Entangled particles break the limit, and that is how we prove that the entanglement is genuine.","former":["bell's inequality","bell inequality","bell inequalities","bell's inequalities","bell test","bell tests"]}},"besselstrale":{"kalla":"847a2448a7","data":{"term":"Bessel beam","kort":"A beam of light or sound that keeps its width instead of spreading out, and that also closes up again behind an obstacle. It is built from waves that come in at an angle from all sides and meet along a common centre line.","former":["bessel beam","bessel beams"]}},"betasonderfall":{"kalla":"8b8a7cb410","data":{"term":"Beta decay","kort":"The decay in which a neutron becomes a proton or vice versa, and the nucleus emits an electron or a positron together with a neutrino. The element changes, but the number of nuclear particles stays the same.","former":["beta decay","beta decays","beta radiation","beta particle","beta particles","beta emitter","beta emitters","beta minus decay","beta plus decay"]}},"bethe-strang":{"kalla":"186175fd23","data":{"term":"Bethe string","kort":"A cluster of particles held together only by their mutual attraction, which can only exist in a system where motion is restricted to a single direction.","former":["bethe string","bethe strings","bethe ansatz"]}},"bifurkation":{"kalla":"f7717ea17f","data":{"term":"Bifurcation","kort":"A point where a small change in a setting, for example a flow or a load, makes a system suddenly change its behaviour, so that a stable state disappears or a new one appears.","former":["bifurcation","bifurcations"]}},"bindningsenergi":{"kalla":"e6f160a22c","data":{"term":"Binding energy","kort":"The energy needed to take apart something that is held together, for example a molecule, an atomic nucleus or a cluster of atoms.","former":["binding energy","binding energies"]}},"blazar":{"kalla":"c0247c7da9","data":{"term":"Blazar","kort":"A galaxy with a supermassive black hole at its centre that spews out a narrow jet of matter at almost the speed of light, where the jet happens to point straight at Earth.","former":["blazar","blazars"]}},"bose-einstein-kondensat":{"kalla":"11b2d089f5","data":{"term":"Bose–Einstein condensate","kort":"The coldest form of matter that can be made: a gas in which all the atoms have dropped into the same quantum state and together behave like a single shared wave.","former":["bose–einstein condensate","bose-einstein condensate","bose–einstein condensates","bose-einstein condensates","condensate","condensates","rubidium condensate","rubidium condensates","potassium condensate","atomic condensate","atomic condensates","molecular condensate","molecular condensates"]}},"boson":{"kalla":"be3016c41f","data":{"term":"Boson","kort":"A particle from the family that is happy to share the same quantum state: the opposite of fermions, which can never share a state with each other.","former":["boson","bosons"]}},"bromsstralning":{"kalla":"5a95b07832","data":{"term":"Bremsstrahlung","kort":"The radiation produced when a fast charged particle is slowed down or deflected, usually by an atomic nucleus. It gives the X-ray tube its broad radiation.","former":["bremsstrahlung","braking radiation"]}},"brottmekanik":{"kalla":"bc44c6c4da","data":{"term":"Fracture mechanics","kort":"The study of how cracks form and spread in a material. It does not calculate how strong a body is on average, but what happens at the tip of a single crack.","former":["fracture mechanics","fracture energy","fracture toughness"]}},"brownsk-rorelse":{"kalla":"f2fb3093aa","data":{"term":"Brownian motion","kort":"The random, jittering motion of small particles in a liquid or gas. It happens because the particles are constantly being pushed by the molecules around them.","former":["brownian motion","brownian motions","brownian movement"]}},"brytningsindex":{"kalla":"64e6f63d11","data":{"term":"Refractive index","kort":"A number that tells you how much more slowly light travels in a material than in a vacuum, and therefore how strongly the light is bent when it enters the material.","former":["refractive index","refractive indices","refractive indexes","index of refraction"]}},"casimireffekten":{"kalla":"311f0b952b","data":{"term":"Casimir effect","kort":"Two mirrors placed very close to each other are pulled together by a force, even though there is nothing between them. The force arises because only some of the vacuum's oscillations fit into the gap.","former":["casimir effect","casimir force","casimir forces"]}},"chandrasekhargransen":{"kalla":"2f09c940b3","data":{"term":"Chandrasekhar limit","kort":"The largest mass a white dwarf can have, about 1.4 solar masses. Above that limit the resistance of the electrons can no longer support the star, and it collapses.","former":["chandrasekhar limit","chandrasekhar mass","chandrasekhar's limit"]}},"chockvag":{"kalla":"c82a7ecf17","data":{"term":"Shock wave","kort":"A pressure wave that travels faster than sound in the material it passes through. Instead of building up the pressure smoothly, it strikes like a wall: pressure, density and temperature jump almost instantly to a new value.","former":["shock wave","shock waves","shockwave","shockwaves","shock-compressed","shock compression"]}},"ckm-matrisen":{"kalla":"b83e9c9052","data":{"term":"CKM matrix","kort":"A table of nine numbers that says how easily each type of quark turns into each other type. The numbers must satisfy a strict mathematical condition, and testing that condition is one of the sharpest tests of the Standard Model of particle physics.","former":["ckm matrix","ckm-matrix","cabibbo angle","quark mixing","unitarity"]}},"comptonspridning":{"kalla":"ecfed3284e","data":{"term":"Compton scattering","kort":"When a high-energy photon bounces off an electron and hands over part of its energy. The photon continues with a longer wavelength, which can only be explained if light behaves as particles.","former":["compton scattering","compton effect","compton wavelength"]}},"cooperpar":{"kalla":"65e2a0afa2","data":{"term":"Cooper pair","kort":"Two electrons that in a superconductor stick together in pairs and move in a coordinated way through the material. As long as the pairs hold together, the current meets no resistance.","former":["cooper pair","cooper pairs"]}},"coulombbarriar":{"kalla":"65c01d9df9","data":{"term":"Coulomb barrier","kort":"The energy threshold two atomic nuclei must get past to come close enough to each other to react, since they repel each other electrically all the way in.","former":["coulomb barrier","coulomb barriers"]}},"cpt-symmetri":{"kalla":"73cc01e138","data":{"term":"CPT symmetry","kort":"The deepest known symmetry in physics: if you simultaneously swap all charges for their opposites, mirror space and let time run backwards, the laws of nature should look exactly the same. The consequence is that a particle and its antiparticle must have exactly the same mass.","former":["cpt symmetry","cpt-symmetry","cpt theorem","cpt violation","cpt invariance"]}},"dekoherens":{"kalla":"4ef7823125","data":{"term":"Decoherence","kort":"When a quantum state leaks information to its surroundings so that the superposition is smeared out. It is the main explanation for why the strangeness of quantum physics is not seen in everyday life.","former":["decoherence","decohere","decoheres","decohered","decoherence time","decoherence times"]}},"deuterium":{"kalla":"620ca4f0af","data":{"term":"Deuterium","kort":"Heavy hydrogen: a hydrogen atom whose nucleus contains a neutron alongside the proton. It occurs naturally in all water, but only in about one hydrogen atom in six thousand.","former":["deuterium","deuteron","deuterons","heavy hydrogen","heavy water"]}},"diamagnetism":{"kalla":"deefd38ebc","data":{"term":"Diamagnetism","kort":"The weak tendency of all substances to be pushed away from a magnetic field instead of being drawn into it. The effect is usually unnoticeable, but it is enough to make graphite, and frogs, float.","former":["diamagnetism","diamagnetic"]}},"diamantstadcell":{"kalla":"e72fb9d5e6","data":{"term":"Diamond anvil cell","kort":"A tabletop tool in which a small sample is squeezed between the tips of two cut diamonds. Since the tips are microscopic, a moderate force is enough to create pressures that otherwise only exist deep inside planets.","former":["diamond anvil cell","diamond anvil cells","diamond anvil","diamond anvils","diamond cell","diamond cells"]}},"diffraktion":{"kalla":"6876e15481","data":{"term":"Diffraction","kort":"The ability of waves to bend around edges and spread out after an opening instead of going dead straight ahead. The effect only becomes clear when the opening or obstacle is about the same size as the wavelength.","former":["diffraction","diffract","diffracts","diffracted","diffractive","light diffraction","electron diffraction","x-ray diffraction"]}},"diffraktionsgitter":{"kalla":"efe5e6f05d","data":{"term":"Diffraction grating","kort":"A surface with thousands of very closely spaced parallel grooves that splits light into its wavelengths. It is the grating that turns a spectrometer into a precision instrument.","former":["diffraction grating","diffraction gratings","grating spectrometer","grating spectrometers","reflection grating","transmission grating","grating equation"]}},"diod":{"kalla":"576d869f0a","data":{"term":"Diode","kort":"A component that lets current through in only one direction. It is based on the junction between two differently doped semiconductor regions, and comes in versions that emit light, that measure light and that keep a voltage constant.","former":["diode","diodes","rectifier","rectifiers","rectifier diode","light-emitting diode","light-emitting diodes","photodiode","photodiodes","zener diode","zener diodes","laser diode","laser diodes","varactor diode","varactor diodes","varactor"]}},"dispersion":{"kalla":"93bf62ab01","data":{"term":"Dispersion","kort":"When waves with different wavelengths travel at different speeds in the same medium. It is why a prism splits white light into a range of colours.","former":["dispersion","dispersion relation","dispersion relations","dispersive"]}},"dopning":{"kalla":"9839b71451","data":{"term":"Doping","kort":"Deliberately mixing a small amount of foreign atoms into a semiconductor material to control how it conducts current. One atom in a million can be enough.","former":["doping","doped","dopant","dopants","n-doped","p-doped","n-type","p-type","boron-doped"]}},"dubbelbrytning":{"kalla":"8276cdc257","data":{"term":"Birefringence","kort":"When a material refracts light by different amounts depending on how the light wave oscillates, so that an image seen through the crystal becomes double. The property is used in everything from screens to strength testing.","former":["birefringence","birefringent","double refraction","wave plate","wave plates","waveplate","waveplates","quarter-wave plate","half-wave plate"]}},"dubbelspaltforsoket":{"kalla":"a685b4af7e","data":{"term":"The double-slit experiment","kort":"The experiment in which a beam passes through two narrow slits and forms a pattern of bright and dark fringes behind them. The fringes show that the beam is a wave, and they appear even when the particles are sent through one at a time.","former":["the double-slit experiment","double-slit experiment","double-slit experiments","double slit experiment","double slit","double slits","double-slit","double-slit interference"]}},"dyning":{"kalla":"f310ec5d7f","data":{"term":"Swell","kort":"Long, even waves that roll on long after the wind that created them has died down, often thousands of kilometres from the storm.","former":["swell","ocean swell","ocean swells"]}},"efterglod":{"kalla":"6e00a65f47","data":{"term":"Afterglow","kort":"The glow that follows a gamma-ray burst in X-rays, visible light and radio waves, when the shock wave from the explosion is slowed down in the gas around it. It can be seen for days or months.","former":["afterglow","afterglows"]}},"ekvivalensprincipen":{"kalla":"d1297c92a6","data":{"term":"The equivalence principle","kort":"The statement that the mass that makes an object sluggish to set in motion is exactly the same mass that makes it heavy, which is why everything falls equally fast.","former":["the equivalence principle","equivalence principle","equivalence principles","principle of equivalence"]}},"elektrisk-dipol":{"kalla":"41014f1389","data":{"term":"Electric dipole","kort":"An object whose positive and negative charges sit a short distance apart, so that one end becomes more positive and the other more negative, without the whole being charged.","former":["electric dipole","electric dipoles","dipole","dipoles","dipole moment","dipole moments","dipole interaction","dipole-dipole interaction","dipolar"]}},"elektron-fonon-koppling":{"kalla":"12a5cfa017","data":{"term":"Electron-phonon coupling","kort":"The measure of how strongly the electrons in a material feel the vibrations of the atoms. If the coupling is strong, the vibrations can bind the electrons together two by two, and the material can become superconducting.","former":["electron-phonon coupling","electron–phonon coupling","electron-phonon couplings","electron-phonon interaction"]}},"elektroninfangning":{"kalla":"76cb83f155","data":{"term":"Electron capture","kort":"A radioactive decay in which the atomic nucleus captures one of the atom's own electrons. A proton in the nucleus then becomes a neutron, and a neutrino is emitted.","former":["electron capture","electron captures"]}},"elektronmikroskop":{"kalla":"cdb9ae179e","data":{"term":"Electron microscope","kort":"A microscope that forms images with electrons instead of light. Since a fast electron behaves like a wave with an extremely short wavelength, it can show details right down to the atomic level.","former":["electron microscope","electron microscopes","electron microscopy","transmission electron microscope","transmission electron microscopes","cryo-electron microscopy","cryo-em","scanning electron microscope","scanning electron microscopes"]}},"elektronvolt":{"kalla":"93c20ae90b","data":{"term":"Electronvolt","kort":"The unit of energy used when calculating with individual particles: the energy an electron gains when it passes through a voltage of one volt. It is vanishingly small in everyday terms: a single joule corresponds to just over six billion billion electronvolts.","former":["electronvolt","electronvolts","electron volt","electron volts","kiloelectronvolt","kiloelectronvolts","megaelectronvolt","megaelectronvolts","gigaelectronvolt","gigaelectronvolts","teraelectronvolt","teraelectronvolts"]}},"elementarladdning":{"kalla":"7606c79fc6","data":{"term":"Elementary charge","kort":"The smallest free electric charge that exists in nature. All charge you can measure on an object is a whole number of these, and the charge of the electron and the proton is exactly one each.","former":["elementary charge","elementary charges"]}},"elliptiskt-flode":{"kalla":"38a4423ea6","data":{"term":"Elliptic flow","kort":"A measure of how unevenly particles are sprayed out in different directions after a collision between two atomic nuclei. The unevenness shows that the matter formed flowed like a liquid, and what shape the collision had.","former":["elliptic flow","anisotropic flow","triangular flow"]}},"entropi":{"kalla":"1e0d9364ae","data":{"term":"Entropy","kort":"A measure of how many different ways a system can be arranged in its small parts without any difference being visible from outside. The greater the entropy, the greater the disorder. In an isolated system, entropy can never decrease.","former":["entropy","entropy increase"]}},"eotvosparametern":{"kalla":"ec22bdcd41","data":{"term":"The Eötvös parameter","kort":"A measure of how differently fast two substances fall. If they fall exactly equally fast, the parameter is zero, and so far every measurement has given exactly zero.","former":["the eötvös parameter","eötvös parameter","eötvös parameters","eotvos parameter","eötvös ratio","eötvös coefficient"]}},"epsilon-nara-noll":{"kalla":"a00a804c3f","data":{"term":"Epsilon-near-zero","kort":"A state in which a material barely responds electrically at all to a light wave of a particular wavelength. The material then becomes unusually sensitive to strong light, so that one beam of light can be controlled by another.","former":["epsilon-near-zero","epsilon near zero","epsilon-near-zero material","epsilon-near-zero materials","enz material","enz materials"]}},"exciterat-tillstand":{"kalla":"d3ee91e8c3","data":{"term":"Excited state","kort":"A state in which an atom, atomic nucleus or molecule carries more energy than its lowest possible state, like a wound-up spring waiting to release its energy.","former":["excited state","excited states","excitation","excitations","de-excited","de-excitation"]}},"exoplanet":{"kalla":"75335283a8","data":{"term":"Exoplanet","kort":"A planet orbiting a star other than the Sun. Several thousand are known today, and most of them are like nothing in our own solar system.","former":["exoplanet","exoplanets","exoplanet atmosphere","exoplanet atmospheres","extrasolar planet","extrasolar planets"]}},"fasdiagram":{"kalla":"694d5e6366","data":{"term":"Phase diagram","kort":"A map of which form a substance takes (solid, liquid or gas) at different pressures and temperatures. The lines on the map show exactly where the substance changes form.","former":["phase diagram","phase diagrams","melting curve","melting curves","phase boundary","phase boundaries","triple point","triple points"]}},"fasforskjutning":{"kalla":"7dd8b05d57","data":{"term":"Phase shift","kort":"How far one wave is ahead of or behind another in its oscillation. A shift of half a wavelength makes two otherwise identical waves cancel each other out completely.","former":["phase shift","phase shifts","phase delay","phase lag","antiphase","phase relationship","phase relationships","phase relation","phase pattern","phase patterns"]}},"fasproblem":{"kalla":"80c2e91815","data":{"term":"The phase problem","kort":"The difficulty that a detector can only measure the strength of a wave, not whether it is positive or negative, so that roughly half of the information is lost in the measurement.","former":["the phase problem","phase problem"]}},"fasvirvel":{"kalla":"8926de9206","data":{"term":"Phase vortex","kort":"A point in a wave pattern where the wave stands still while the phase of the wave goes round the point, like the hands of a clock. Such points can carry angular momentum.","former":["phase vortex","phase vortices","phase vortexes","phase singularity","phase singularities"]}},"fermion":{"kalla":"e6ec751a13","data":{"term":"Fermion","kort":"A particle from the family that can never share a quantum state with an identical particle. It is this rule that gives matter its extent and atoms their shell structure.","former":["fermion","fermions","fermionic","pauli principle","pauli exclusion principle","exclusion principle","pauli's exclusion principle"]}},"fonon":{"kalla":"5d51876fd3","data":{"term":"Phonon","kort":"The smallest portion of vibration that can exist in a solid. Sound and heat in a crystal are counted as a swarm of such portions, rather as light is counted in photons.","former":["phonon","phonons","phonon signal","phonon signals"]}},"forangningskylning":{"kalla":"bdf71e7ec7","data":{"term":"Evaporative cooling","kort":"The method of cooling something by letting the fastest particles escape. Those left behind have a lower average energy, that is, a lower temperature.","former":["evaporative cooling","evaporation"]}},"forgrovning":{"kalla":"def60b3459","data":{"term":"Coarsening","kort":"When a pattern of many small regions grows together over time into fewer and larger ones, as when small oil droplets merge into big ones.","former":["coarsening","wave coarsening"]}},"forstarkt-spontan-emission":{"kalla":"0b692342b5","data":{"term":"Amplified spontaneous emission","kort":"When light from one atom makes other atoms emit identical light in the same direction, so that the signal grows like an avalanche. It is the same amplification as in a laser, but without mirrors.","former":["amplified spontaneous emission","stimulated emission"]}},"fotolitografi":{"kalla":"cf77f3e534","data":{"term":"Photolithography","kort":"A manufacturing method in which a pattern is drawn with light in a light-sensitive layer, instead of being milled or printed mechanically. It lies behind almost every computer chip.","former":["photolithography","lithography"]}},"foton":{"kalla":"b442546235","data":{"term":"Photon","kort":"The smallest indivisible packet of energy of light: a particle without mass that always moves at the speed of light. Its energy is determined by the frequency of the light, that is, by its colour.","former":["photon","photons","light particle","light particles","x-ray photon","x-ray photons","background photon","background photons"]}},"fotonisk-kristall":{"kalla":"71bf675294","data":{"term":"Photonic crystal","kort":"A material with a built-in, regular pattern on the nanoscale that determines which wavelengths of light are allowed through: a kind of crystal lattice for light.","former":["photonic crystal","photonic crystals"]}},"fotosfar":{"kalla":"3802cf7d68","data":{"term":"Photosphere","kort":"The thin layer of a star where the gas finally becomes transparent and the light can leave it. It is the visible “surface” of the star, but it consists of gas, not of anything solid.","former":["photosphere","photospheres","the sun's photosphere","solar photosphere"]}},"frekvenskam":{"kalla":"0d4c375f69","data":{"term":"Frequency comb","kort":"Light that does not contain all colours but only a row of sharp, evenly spaced frequencies. If you plot them, the spectrum looks like the teeth of a comb.","former":["frequency comb","frequency combs","optical frequency comb","optical frequency combs"]}},"fresnellins":{"kalla":"fd786a7840","data":{"term":"Fresnel lens","kort":"A lens that has been divided into thin rings and flattened, so that it collects light almost like a thick glass lens but weighs a fraction as much. It was invented for lighthouses in the 1820s and is used today in everything from spotlights to solar concentrators.","former":["fresnel lens","fresnel lenses"]}},"frielektronlaser":{"kalla":"9dd16a4189","data":{"term":"Free-electron laser","kort":"A facility that makes laser-like X-rays from a beam of free electrons instead of from a material. The electrons are forced to snake through a row of magnets and radiate as they do so.","former":["free-electron laser","free-electron lasers","free electron laser","free electron lasers","x-ray laser","x-ray lasers"]}},"fyrvagsblandning":{"kalla":"3268f9f0f0","data":{"term":"Four-wave mixing","kort":"An optical process in which three light waves interact in a material and together create a fourth wave with a new frequency. It only works when the light is very strong.","former":["four-wave mixing","four wave mixing","nonlinear optics","non-linear optics"]}},"galaxhop":{"kalla":"da97976335","data":{"term":"Galaxy cluster","kort":"Hundreds to thousands of galaxies held together by their shared gravity. Galaxy clusters are the largest structures in the universe that still hold together.","former":["galaxy cluster","galaxy clusters","cluster of galaxies","clusters of galaxies"]}},"gammablixt":{"kalla":"edc3a01e2a","data":{"term":"Gamma-ray burst","kort":"The brightest explosions in the universe: a few seconds of gamma radiation from an event billions of light years away. During that short moment, a burst shines brighter than all the stars in its galaxy put together.","former":["gamma-ray burst","gamma-ray bursts","gamma ray burst","gamma ray bursts","long gamma-ray bursts","short gamma-ray bursts","grb","grbs"]}},"gammastralning":{"kalla":"606aa7b1e7","data":{"term":"Gamma radiation","kort":"Electromagnetic radiation with the very shortest wavelength and the highest energy per photon. It comes from atomic nuclei and from the most violent events in the universe, and is strongly ionising.","former":["gamma radiation","gamma ray","gamma rays","gamma photon","gamma photons","gamma quanta"]}},"gitter":{"kalla":"7641e9a790","data":{"term":"Lattice","kort":"The regular, repeated pattern that atoms form in a crystal. The Swedish word is also used for optical gratings: dense patterns of slits or grooves that split light into its colours.","former":["lattice","lattices","crystal lattice","crystal lattices","atomic lattice","metal lattice","lattice structure","lattice structures","honeycomb lattice","silicon lattice"]}},"gitter-qcd":{"kalla":"b6da3a53fd","data":{"term":"Lattice QCD","kort":"A way of calculating with the strong force by replacing space and time with a grid of points and letting a supercomputer work its way through point by point. Today it is the only method that gives answers directly from the theory, without guesses along the way.","former":["lattice qcd","lattice-qcd","lattice qcd calculation","lattice qcd calculations","lattice calculation","lattice calculations","spacetime lattice"]}},"glasovergang":{"kalla":"5050be2fa1","data":{"term":"Glass transition","kort":"The process in which a liquid solidifies without crystallising: the molecules keep the disorder of the liquid, but the motion becomes so sluggish that the substance behaves like a solid.","former":["glass transition","glass transitions","glass transition temperature","glass transition temperatures","glassy","amorphous"]}},"gluon":{"kalla":"9a4593739a","data":{"term":"Gluon","kort":"The particle that transmits the strong force between quarks. Unlike the photons of light, gluons also pull on each other, and that is why the force does not weaken with distance.","former":["gluon","gluons","gluon exchange"]}},"grafen":{"kalla":"d2ad2cd458","data":{"term":"Graphene","kort":"A single layer of carbon atoms arranged in a honeycomb pattern. It is the thinnest material that can be made, one atom thick, and at the same time one of the strongest and most electrically conductive.","former":["graphene","bilayer graphene","graphene sheet","graphene sheets","graphene layer","graphene layers"]}},"granulation":{"kalla":"fd4ac69574","data":{"term":"Granulation","kort":"The bubbly pattern covering the Sun's surface: bright cells of rising hot gas, separated by darker lanes where the gas has cooled and is sinking back.","former":["granulation","granule","granules","solar granule","solar granules","solar granulation"]}},"gravitationslinsning":{"kalla":"252556ae3d","data":{"term":"Gravitational lensing","kort":"Light passing close to a heavy mass is bent, so that the image of what lies behind is shifted, stretched or doubled. The effect makes it possible to weigh mass that cannot be seen.","former":["gravitational lensing","gravitational lens","gravitational lenses","gravitational lens effect","weak gravitational lensing","strong gravitational lensing","weak lensing","strong lensing","lensing"]}},"gravitationsvag":{"kalla":"d1c3e30f54","data":{"term":"Gravitational wave","kort":"A ripple in spacetime that spreads out at the speed of light when heavy objects accelerate, for example when two black holes or neutron stars orbit each other and collide.","former":["gravitational wave","gravitational waves","gravitational-wave detector","gravitational-wave detectors","gravitational wave detector","gravitational wave detectors"]}},"griffithlangden":{"kalla":"5ee9e9c32f","data":{"term":"Griffith length","kort":"The critical crack length at which a fracture switches from stable to self-propagating. If the crack is shorter it stays put; if it is longer it races off through the material.","former":["griffith length","griffith lengths","griffith criterion","griffith's criterion","griffith crack length"]}},"grupphastighet":{"kalla":"fbf141aed2","data":{"term":"Group velocity","kort":"The speed of a wave pulse as a whole, to be distinguished from the phase velocity, which is the speed of the individual wave crests inside the pulse. The two are rarely equal.","former":["group velocity","group velocities","group speed","phase velocity","phase velocities"]}},"halleffekten":{"kalla":"59c78483bc","data":{"term":"Hall effect","kort":"When a current-carrying plate gets a voltage across it when placed in a magnetic field. The effect reveals both the strength of the field and the sign of the charge carriers.","former":["hall effect","hall voltage","hall sensor","hall sensors","hall resistance","hall measurement","hall measurements"]}},"halveringstid":{"kalla":"b4216c5cca","data":{"term":"Half-life","kort":"The time it takes for half of the nuclei in a radioactive substance to decay. It is the same however much or little is left, and cannot be influenced.","former":["half-life","half-lives","half life","half lives"]}},"halvledare":{"kalla":"ab589bda1a","data":{"term":"Semiconductor","kort":"A material that conducts current worse than a metal but better than an insulator, and whose conductivity can also be controlled. It is this controllability that makes all modern electronics possible.","former":["semiconductor","semiconductors","semiconductor material","semiconductor materials","semiconductor component","semiconductor components","semiconductor industry"]}},"halvskugga":{"kalla":"168559dc79","data":{"term":"Penumbra","kort":"The outer, grey part of a shadow, reached by light from part of the light source but not from all of it. In the Moon's penumbra you see the Sun partly covered.","former":["penumbra","penumbrae","penumbras","penumbral","half-shadow"]}},"handelsehorisont":{"kalla":"db7c61bd98","data":{"term":"Event horizon","kort":"The boundary around a black hole where the speed of light would be needed to get free. Inside it all paths lead inwards, and nothing that passes can get out again.","former":["event horizon","event horizons","schwarzschild radius","schwarzschild radii"]}},"het-jupiter":{"kalla":"43b79e9d90","data":{"term":"Hot Jupiter","kort":"A giant planet like Jupiter that orbits close to its star, often in just a few days. The first exoplanet found around a Sun-like star turned out to be one, against all expectations.","former":["hot jupiter","hot jupiters","hot jupiter planet","hot jupiter planets"]}},"higgsbosonen":{"kalla":"1b0ed3e346","data":{"term":"The Higgs boson","kort":"The particle that revealed the Higgs field: the invisible field that fills all of space and gives the elementary particles their mass. It was found at CERN in 2012, almost fifty years after it was predicted.","former":["the higgs boson","higgs boson","higgs bosons","higgs particle","higgs particles","higgs field","higgs mechanism"]}},"hogharmonisk-generering":{"kalla":"7adf035e4c","data":{"term":"High-harmonic generation","kort":"A way of making extremely short-wavelength light by firing a strong laser pulse into a gas, which responds by emitting light at many times the original frequency.","former":["high-harmonic generation","high harmonic generation","high-order harmonic generation","high-harmonic","high harmonics","high-order harmonics"]}},"hogladdad-jon":{"kalla":"3cb70736c8","data":{"term":"Highly charged ion","kort":"An atom that has had many or even all of its electrons torn away and therefore carries a strongly positive charge. They occur naturally in the outer layers of the Sun and are made artificially in accelerators and ion sources.","former":["highly charged ion","highly charged ions","highly charged"]}},"hong-ou-mandel-effekten":{"kalla":"b133ae7496","data":{"term":"Hong-Ou-Mandel effect","kort":"Two identical particles of light meeting at a half-silvered mirror always leave it in the same direction, never in different ones. The effect is used as a test of whether two photons are truly indistinguishable.","former":["hong-ou-mandel effect","hong–ou–mandel effect","hong-ou-mandel interference","hong–ou–mandel interference","hom effect","two-photon interference"]}},"hornreflektor":{"kalla":"7b5e9bf546","data":{"term":"Corner reflector","kort":"Three mirror surfaces mounted as in the corner of a cube, at right angles to each other. Light that hits them is thrown back along exactly the same path it came, whichever direction it comes from.","former":["corner reflector","corner reflectors","retroreflector","retroreflectors","corner cube","corner cubes","corner-cube reflector","corner-cube reflectors"]}},"hydrogel":{"kalla":"1c5cf3f301","data":{"term":"Hydrogel","kort":"A soft material made of long molecular chains linked into a network and filled with water. It can consist mostly of water and still keep its shape, like jelly.","former":["hydrogel","hydrogels"]}},"hyperfinstruktur":{"kalla":"b41aaf1a2d","data":{"term":"Hyperfine structure","kort":"An extremely small splitting of an atom's energy levels, caused by the atomic nucleus having its own magnetic field and a charge that is not concentrated at a single point. The splitting means that each spectral line is really a bundle of lines.","former":["hyperfine structure","hyperfine structures","hyperfine","hyperfine level","hyperfine levels","hyperfine transition","hyperfine transitions","hyperfine splitting","hyperfine splittings"]}},"hyperon":{"kalla":"23fddec8c5","data":{"term":"Hyperon","kort":"A heavy relative of the proton and neutron that contains at least one strange quark. Hyperons are formed in collisions between particles and decay within a fraction of a millionth of a second.","former":["hyperon","hyperons","hyperon beam","hyperon beams"]}},"hysteres":{"kalla":"b619822682","data":{"term":"Hysteresis","kort":"When a material responds differently on the way up and on the way down, so that its state depends on what has happened before and not just on how hard it is being pulled right now.","former":["hysteresis","hysteresis loop","hysteresis loops","hysteresis loss","hysteresis losses"]}},"icke-reciprok":{"kalla":"d765c5742e","data":{"term":"Non-reciprocal","kort":"Says that an influence is not the same in both directions: that A affects B in a certain way does not mean that B affects A in the same way.","former":["non-reciprocal","nonreciprocal","non-reciprocity","nonreciprocity"]}},"impuls":{"kalla":"c05c03fd26","data":{"term":"Impulse","kort":"The effect of a force over a certain time, that is, the force multiplied by how long it acts. The impulse is exactly equal to the change in momentum it produces.","former":["impulse","impulses"]}},"indirekt-bandgap":{"kalla":"7f1bc9a055","data":{"term":"Indirect band gap","kort":"Two kinds of semiconductor. In one, an electron can fall down and emit light on its own; in the other, the lattice has to vibrate at the same time, and then the material hardly glows at all.","former":["direct band gap","direct band gaps","direct bandgap","direct bandgaps","indirect band gap","indirect band gaps","indirect bandgap","indirect bandgaps"]}},"interferens":{"kalla":"2bf9c83b8b","data":{"term":"Interference","kort":"When two waves meet and add together: crest on crest reinforce each other, while crest on trough cancel each other out.","former":["interference","interference pattern","interference patterns","constructive interference","destructive interference"]}},"interferometer":{"kalla":"0855791e76","data":{"term":"Interferometer","kort":"An instrument that splits a beam of light in two and then puts the two beams back together. How the waves reinforce or cancel each other reveals very small differences in distance.","former":["interferometer","interferometers","laser interferometer","laser interferometers","interferometry"]}},"invers-betasonderfall":{"kalla":"a993741de1","data":{"term":"Inverse beta decay","kort":"The reaction that makes it possible to catch an antineutrino at all: it hits a proton, turns it into a neutron and sends off a positron. Almost all neutrino detectors at nuclear power plants are based on it.","former":["inverse beta decay","inverse beta decays"]}},"invers-comptonspridning":{"kalla":"7e9b4cb149","data":{"term":"Inverse Compton scattering","kort":"When a very fast electron collides with a particle of light and kicks it up to a much higher energy. Ordinary light can in this way be turned into X-rays or gamma radiation.","former":["inverse compton scattering","inverse compton effect","inverse compton"]}},"iribarrental":{"kalla":"02f1dc1df3","data":{"term":"The Iribarren number","kort":"A single number that predicts how a wave will break on a beach, built from the slope of the bottom and the steepness of the wave.","former":["the iribarren number","iribarren number","iribarren numbers","iribarren parameter","surf similarity parameter"]}},"isjatte":{"kalla":"b0d12e50de","data":{"term":"Ice giant","kort":"A planet like Neptune and Uranus: considerably larger than Earth, but made mostly of water, methane and ammonia instead of hydrogen and helium like the gas giants.","former":["ice giant","ice giants","ice giant planet","ice giant planets","diamond rain"]}},"isobar":{"kalla":"185637d092","data":{"term":"Isobar","kort":"Two atomic nuclei that contain the same total number of nuclear particles but different numbers of protons. They weigh almost exactly the same and are still different elements.","former":["isobar","isobars","isobaric nucleus","isobaric nuclei"]}},"isotop":{"kalla":"4fa86bd317","data":{"term":"Isotope","kort":"Atoms of the same element but with different numbers of neutrons in the nucleus. They behave almost identically chemically, but differ in mass and in how stable they are.","former":["isotope","isotopes","isotopic","isotope ratio","isotope ratios","isotopic ratio","nuclide","nuclides","hydrogen isotope","hydrogen isotopes","parent isotope","radium isotope","radium isotopes"]}},"jonfalla":{"kalla":"bb91d2d139","data":{"term":"Ion trap","kort":"A device that holds individual charged atoms in the middle of a vacuum with electric and magnetic fields, without them touching any wall. Trapped ions are used as qubits in quantum computers and in the world's most precise clocks.","former":["ion trap","ion traps","ion-trap","trapped ion","trapped ions","paul trap","paul traps","surface-electrode trap","surface electrode trap"]}},"jordens-karna":{"kalla":"fc8c99af73","data":{"term":"Earth's core","kort":"The innermost part of the Earth, a sphere of mainly iron and nickel with a radius of about 3 500 kilometres. The outer part is liquid, the innermost is solid.","former":["earth's core","the earth's core","inner core","outer core","the inner core","the outer core"]}},"jordmanteln":{"kalla":"644eb697e4","data":{"term":"Earth's mantle","kort":"The layer of hot rock, just under 2 900 kilometres thick, between the Earth's crust and the core. It makes up about two thirds of the Earth's mass.","former":["earth's mantle","the earth's mantle","mantle"]}},"josephsonovergang":{"kalla":"15f96129f4","data":{"term":"Josephson junction","kort":"A thin barrier between two regions of a superconductor or a superfluid, through which the quantum wave can just leak. It makes an invisible quantum phase measurable.","former":["josephson junction","josephson junctions","josephson effect"]}},"karakteristisk-rontgenstralning":{"kalla":"7fb846fe96","data":{"term":"Characteristic X-rays","kort":"The X-ray light an atom emits when a gap in an inner electron shell is filled again. The wavelengths are different for each element and work like a fingerprint.","former":["characteristic x-rays","characteristic x-ray","characteristic x-radiation","characteristic radiation","x-ray line","x-ray lines","x-ray fluorescence"]}},"karnfusion":{"kalla":"90523a870a","data":{"term":"Nuclear fusion","kort":"Two light atomic nuclei are joined into a heavier one, and part of the mass is released as energy. It is nuclear fusion that makes the Sun and all other stars shine.","former":["nuclear fusion","fusion","fusion reaction","fusion reactions","fusion reactor","fusion reactors","fusion power","fusion energy","fusion rate","hydrogen fusion","cold fusion"]}},"karnklocka":{"kalla":"7e44e09ab6","data":{"term":"Nuclear clock","kort":"A clock that keeps time using a transition between two energy levels in an atomic nucleus, instead of between two levels of the electrons in an atom. The only nucleus that can be used so far is thorium-229.","former":["nuclear clock","nuclear clocks","thorium clock","thorium clocks","thorium nuclear clock"]}},"karnskugga":{"kalla":"820e2d9291","data":{"term":"Umbra","kort":"The innermost part of a shadow, which no light at all from the light source reaches. If you stand in the Moon's umbra, the Sun is completely covered.","former":["umbra","umbrae","umbras","umbral","full shadow"]}},"kavitet":{"kalla":"6aa700bb1c","data":{"term":"Cavity","kort":"A small enclosed space between mirrors or metal surfaces in which only certain wavelengths fit. The cavity therefore determines which electromagnetic oscillations can exist in it at all.","former":["cavity","cavities","dark cavity","optical cavity","optical cavities","resonator","resonators","ring resonator","ring resonators","terahertz resonator","terahertz resonators","mirror cavity","mechanical resonator","mechanical resonators"]}},"kelvin-helmholtz-instabilitet":{"kalla":"46eaf614e7","data":{"term":"Kelvin–Helmholtz instability","kort":"What happens when two layers of gas or liquid slide past each other at different speeds: the boundary between them ripples, the waves grow and roll up into vortices.","former":["kelvin–helmholtz instability","kelvin–helmholtz instabilities","kelvin-helmholtz instability","kelvin-helmholtz instabilities"]}},"kelvinvag":{"kalla":"33b84dc6f4","data":{"term":"Kelvin wave","kort":"A spiral-shaped wave that runs along the centre line of a vortex, rather like a wave along a stretched rope. It is named after Lord Kelvin, who proposed it in 1880.","former":["kelvin wave","kelvin waves","kelvin wave turbulence"]}},"kemisk-potential":{"kalla":"87c4cb0ef8","data":{"term":"Chemical potential","kort":"A measure of how much a system's energy changes when a single particle is added or removed. Particles move to where the potential is lowest, rather as water flows downhill.","former":["chemical potential","chemical potentials"]}},"kerreffekten":{"kalla":"09fdc12b4f","data":{"term":"Kerr effect","kort":"When a material's refractive index is changed by a strong electric field. In a powerful laser beam it is the light's own field that does it, and then the beam can focus itself.","former":["kerr effect","optical kerr effect","self-focusing","self focusing"]}},"kilonova":{"kalla":"1a2aa9f241","data":{"term":"Kilonova","kort":"A burst of light lasting a few days after two neutron stars have collided. The light comes from radioactive elements formed in the ejected material, among them gold and platinum.","former":["kilonova","kilonovae","kilonovas"]}},"kiralitet":{"kalla":"39125abfdf","data":{"term":"Chirality","kort":"The property of being different from your own mirror image, like a right and a left hand. Molecules, crystals and even light can be chiral.","former":["chirality","chiral"]}},"klyvningsprodukt":{"kalla":"2fe346c11b","data":{"term":"Fission product","kort":"The pieces left over when a heavy atomic nucleus such as uranium splits. They are almost always radioactive, and it is they, not the uranium, that make spent nuclear fuel dangerous and hot for centuries.","former":["fission product","fission products","fission fragment","fission fragments"]}},"knackning":{"kalla":"a51f5c25e0","data":{"term":"Buckling","kort":"When a thin wall, rod or shell under load suddenly gives way and takes on a completely new shape, instead of just being compressed a little at a time.","former":["buckling"]}},"koherens":{"kalla":"d2ceb1c153","data":{"term":"Coherence","kort":"How well the waves in a beam of light keep in step with each other. Coherent light has a fixed phase relationship between different parts of the beam and can therefore give clear interference patterns.","former":["coherence","coherent","coherent light","incoherent","incoherent light","incoherence","partially coherent","coherence length","coherence lengths"]}},"kollapsmodell":{"kalla":"9d1ac4e58e","data":{"term":"Collapse model","kort":"A theory that modifies quantum mechanics by adding a small random disturbance, so that superpositions collapse by themselves. The heavier the object, the faster it happens.","former":["collapse model","collapse models","spontaneous collapse","spontaneous collapse model","spontaneous collapse models","collapse theory","collapse theories"]}},"kolnanoror":{"kalla":"d4d4c67926","data":{"term":"Carbon nanotube","kort":"A hollow tube of pure carbon, about a nanometre in diameter, built from the same hexagonal pattern as graphite. It is stiffer than steel along its length and weighs almost nothing.","former":["carbon nanotube","carbon nanotubes","nanotube","nanotubes","carbon nanotube foam","nanotube forest","nanotube forests"]}},"kolvattenacceleration":{"kalla":"714214ebc5","data":{"term":"Wakefield acceleration","kort":"A way of giving charged particles enormous speed over a very short distance: a powerful laser pulse is fired through a plasma and leaves behind a wave of charge that electrons can surf on.","former":["wakefield acceleration","wakefield","wakefields","wake wave","wake waves","plasma accelerator","plasma accelerators","plasma acceleration","plasma wave","plasma waves","single-stage accelerator","single-stage accelerators","laser wakefield acceleration"]}},"komet":{"kalla":"17772442dc","data":{"term":"Comet","kort":"A lump of ice and dust from the cold outskirts of the solar system. If it comes close to the Sun, the ice vaporises and forms a glowing cloud of gas and a tail.","former":["comet","comets","comet nucleus","comet nuclei","cometary nucleus","comet tail","comet tails","dark comet","dark comets"]}},"korona":{"kalla":"586e9d681c","data":{"term":"Corona","kort":"A star's outermost atmosphere: for the Sun, a thin veil of gas at a million degrees that can only be seen with the naked eye during a total solar eclipse.","former":["corona","coronae","coronas","solar corona","stellar corona","stellar coronae","coronal"]}},"korrelationsspektroskopi":{"kalla":"fa6e77414b","data":{"term":"Correlation spectroscopy","kort":"A measurement method in which two systems are examined at the same time and you only ask whether they responded the same or differently. Disturbances that affect both in the same way then drop out by themselves.","former":["correlation spectroscopy"]}},"kosmisk-mikrovagsbakgrund":{"kalla":"83f5ca8ca5","data":{"term":"Cosmic microwave background","kort":"The faint light that fills all of space and is left over from the universe's hot youth. It is the oldest radiation that can be seen, emitted when the universe was just under 400 000 years old.","former":["cosmic microwave background","cosmic microwave background radiation","microwave background","cosmic background radiation","cmb"]}},"kosmisk-stralning":{"kalla":"bf6316ac57","data":{"term":"Cosmic rays","kort":"Charged particles, mostly protons, that come rushing through space at enormous speeds and constantly rain down on the Earth. The Swedish name, cosmic radiation, is misleading: it is not radiation in the usual sense but particles.","former":["cosmic rays","cosmic ray","cosmic radiation","cosmic particles","cosmic-ray"]}},"kosmologiska-konstanten":{"kalla":"79e6cbcaf2","data":{"term":"The cosmological constant","kort":"A term in Einstein's equations, written Λ (lambda), that gives empty space a built-in energy. Today it is the simplest explanation for why the expansion of the universe is accelerating.","former":["the cosmological constant","cosmological constant"]}},"kvadrupolmoment":{"kalla":"d21d5bcada","data":{"term":"Quadrupole moment","kort":"A measure of how much a charge distribution deviates from being spherical. A positive value means elongated like a rugby ball, negative means flattened like a lens, and zero means a perfect sphere.","former":["quadrupole moment","quadrupole moments","quadrupole","quadrupoles","electric quadrupole moment"]}},"kvant-halleffekten":{"kalla":"77bb6556bb","data":{"term":"Quantum Hall effect","kort":"What happens when electrons are forced into a thin layer, cooled almost to absolute zero and exposed to a strong magnetic field: they arrange themselves in a rigid quantum state in which the resistance takes exact, definite values.","former":["quantum hall effect","quantum hall state","quantum hall states","fractional quantum hall effect","integer quantum hall effect","filling factor","filling factors"]}},"kvantbrunn":{"kalla":"d7df2347e0","data":{"term":"Quantum well","kort":"A very thin layer of a semiconductor material, sandwiched between two other materials, in which electrons are trapped so that they can only move along the layer and not across it.","former":["quantum well","quantum wells"]}},"kvantdator":{"kalla":"b3fbbabe49","data":{"term":"Quantum computer","kort":"A computer that calculates according to the rules of quantum mechanics. Its memory cells, qubits, can be in a mixture of 0 and 1 at the same time, which opens up new ways of tackling certain problems.","former":["quantum computer","quantum computers","quantum computing","quantum computation","quantum computations","quantum algorithm","quantum algorithms"]}},"kvantdroppe":{"kalla":"61c20eaf5a","data":{"term":"Quantum droplet","kort":"A cloud of extremely cold particles that holds together by itself, without a container and without walls, rather like a drop of water, although an ordinary drop is millions of times denser.","former":["quantum droplet","quantum droplets"]}},"kvantelektrodynamik":{"kalla":"20c8553218","data":{"term":"Quantum electrodynamics","kort":"The theory of how light and electrically charged matter interact. It describes the electric force as an exchange of photons and is the most precisely tested theory in physics.","former":["quantum electrodynamics","qed"]}},"kvantmekanik":{"kalla":"8713afcf3e","data":{"term":"Quantum mechanics","kort":"The theory of the very smallest building blocks of matter. There, energy comes in definite portions, particles behave like waves, and nature answers with probabilities instead of certainties.","former":["quantum mechanics","quantum mechanical","quantum-mechanical","quantum mechanically","quantum physics","quanta","quantum state","quantum states"]}},"kvantprick":{"kalla":"743aa75631","data":{"term":"Quantum dot","kort":"A crystal so small that the electrons inside it may only have certain definite energies. The size then determines which colour the dot can absorb and emit.","former":["quantum dot","quantum dots","quantum dot display","quantum dot displays"]}},"kvantsammanflatning":{"kalla":"4211eedbe3","data":{"term":"Quantum entanglement","kort":"A quantum phenomenon in which two particles share a common state, so that a measurement on one immediately determines the result for the other, regardless of the distance between them.","former":["quantum entanglement","entanglement","entangled","entangle","entangles","polarisation entanglement","polarization entanglement"]}},"kvantsprang":{"kalla":"91fae2151e","data":{"term":"Quantum jump","kort":"When a small system changes energy state without passing through any position in between. The change happens all at once, and the moment cannot be calculated in advance.","former":["quantum jump","quantum jumps","quantum leap","quantum leaps","quantum jumping"]}},"kvark":{"kalla":"48efd25e1e","data":{"term":"Quark","kort":"The building block that protons, neutrons and their relatives are made of. Quarks come in six types and can never be taken out one by one; they always stick together in groups.","former":["quark","quarks","up quark","up quarks","down quark","down quarks","strange quark","strange quarks","charm quark","charm quarks","top quark","top quarks","bottom quark","bottom quarks","antiquark","antiquarks","quark flavour","quark flavours","quark flavor","quark flavors","pentaquark","pentaquarks"]}},"kvark-gluonplasma":{"kalla":"0a75ab580e","data":{"term":"Quark-gluon plasma","kort":"A state of matter so hot and dense that the quarks and gluons are no longer stuck inside individual protons or neutrons, but move freely among each other. The universe consisted of it during its first millionths of a second.","former":["quark-gluon plasma","quark–gluon plasma","quark gluon plasma","quark-gluon plasmas","primordial matter"]}},"kvasar":{"kalla":"5e72bb1df6","data":{"term":"Quasar","kort":"The core of a distant galaxy that shines brighter than the whole galaxy around it. The light comes from gas that is violently heated as it falls towards a supermassive black hole.","former":["quasar","quasars"]}},"kvasikristall":{"kalla":"31946a49be","data":{"term":"Quasicrystal","kort":"A substance whose atoms are strictly ordered but in a pattern that never repeats exactly. Quasicrystals can have symmetries, such as fivefold symmetry, that an ordinary crystal can never have.","former":["quasicrystal","quasicrystals","quasicrystalline"]}},"kvasipartikel":{"kalla":"8b06e85def","data":{"term":"Quasiparticle","kort":"A pattern in how a great many particles move together, which behaves exactly as if it were a particle of its own with a definite position, mass and charge, even though it is not made of anything of its own.","former":["quasiparticle","quasiparticles","quasi-particle","quasi-particles"]}},"kvavevakanscentrum":{"kalla":"3c641ce971","data":{"term":"Nitrogen-vacancy centre","kort":"A small defect in a diamond's crystal, where a nitrogen atom sits next to an empty site. The electrons there have a spin that can be set and read out with light, even at room temperature.","former":["nitrogen-vacancy centre","nitrogen-vacancy centres","nitrogen-vacancy center","nitrogen-vacancy centers","nitrogen vacancy","nitrogen vacancies","nv centre","nv centres","nv center","nv centers","nv-centre","nv-center"]}},"lagrangepunkt":{"kalla":"936e89ffec","data":{"term":"Lagrange point","kort":"One of five places in a system of two large celestial bodies where a small object can keep pace with the orbit without falling behind or rushing ahead. Space telescopes are often parked in the one lying directly away from the Sun as seen from Earth.","former":["lagrange point","lagrange points","lagrangian point","lagrangian points","libration point","libration points"]}},"lambdapartikel":{"kalla":"a175881bf7","data":{"term":"Lambda particle","kort":"The lightest hyperon: an uncharged relative of the neutron in which one of the quarks is replaced by the heavier strange quark. It lives only a tenth of a billionth of a second or so and gives itself away through the V-shaped pair of tracks its decay leaves behind.","former":["lambda particle","lambda particles","lambda hyperon","lambda hyperons","lambda baryon","lambda baryons","antilambda","antilambdas","lambda decay","lambda decays"]}},"landauers-princip":{"kalla":"682f6931a2","data":{"term":"Landauer's principle","kort":"The principle that erasing information always costs energy. Erasing a single bit requires at least a definite amount of heat to be given off to the surroundings, and the amount grows with the temperature.","former":["landauer's principle","landauer principle","landauer's limit","landauer limit"]}},"langdkontraktion":{"kalla":"1ba5585021","data":{"term":"Length contraction","kort":"When an object is measured as shorter in the direction of motion when it rushes past at high speed. The effect is the necessary counterpart to time passing more slowly.","former":["length contraction","lorentz contraction","lorentz–fitzgerald contraction","lorentz-fitzgerald contraction"]}},"laser":{"kalla":"344c24d89d","data":{"term":"Laser","kort":"A light source that emits a narrow, sharply directed beam in which all the light waves have the same wavelength and oscillate in step. The name is an abbreviation of light amplification by stimulated emission of radiation.","former":["laser","lasers","laser beam","laser beams","laser pulse","laser pulses","laser light","diode laser","diode lasers","precision laser","precision lasers","terahertz laser","terahertz lasers","titanium-sapphire laser","titanium-sapphire lasers","ti:sapphire laser","fibre laser","fibre lasers","fiber laser","fiber lasers"]}},"laserfilament":{"kalla":"5504cb8e37","data":{"term":"Laser filament","kort":"A thin, long thread of ionised air that forms when an extremely short and powerful laser pulse focuses itself. The thread can be much longer than an ordinary lens can keep a beam focused.","former":["laser filament","laser filaments","laser filamentation","plasma filament","plasma filaments"]}},"laserkylning":{"kalla":"5c1c1c39fa","data":{"term":"Laser cooling","kort":"Slowing atoms down with light until they almost stand still, which corresponds to temperatures only millionths of a degree above absolute zero. The method is the foundation of today's atomic clocks and quantum gases.","former":["laser cooling","laser-cooled","laser cooled","doppler cooling","magneto-optical trap","magneto-optical traps","optical molasses"]}},"lepton":{"kalla":"821cd2477f","data":{"term":"Lepton","kort":"The particles of matter that are not affected by the strong force and can therefore travel alone. The electron is the everyday lepton, and the family also includes the muon, the tauon and the three neutrinos.","former":["lepton","leptons","tau lepton","tau leptons","tauon","tauons","antilepton","antileptons","lepton number"]}},"lidar":{"kalla":"c7394827f2","data":{"term":"Lidar","kort":"A rangefinder that sends out short laser pulses and times the echo. It builds up a three-dimensional map of its surroundings, point by point.","former":["lidar","lidars","lidar system","lidar systems"]}},"ljusar":{"kalla":"ad095f0dfd","data":{"term":"Light year","kort":"The distance light travels in a year: just under ten trillion kilometres. Despite the name, the light year is a measure of length, not of time.","former":["light year","light years","light-year","light-years"]}},"ljuskurva":{"kalla":"670a6aaf39","data":{"term":"Light curve","kort":"A diagram of how the brightness of a celestial body changes over time. From the repetitions in the curve you can work out, for example, how fast an asteroid rotates.","former":["light curve","light curves","lightcurve","lightcurves"]}},"lorentzinvarians":{"kalla":"075b5ce5b7","data":{"term":"Lorentz invariance","kort":"The requirement that the laws of nature look exactly the same however fast you are moving, and that the speed of light in a vacuum is the same for everyone. It is the assumption on which the whole theory of relativity rests.","former":["lorentz invariance","lorentz invariant","lorentz-invariant","lorentz violation","lorentz invariance violation","violation of lorentz invariance"]}},"magisk-vinkel":{"kalla":"196fdd3f1d","data":{"term":"Magic angle","kort":"The twist of about 1.1 degrees between two layers of graphene that makes the material suddenly start conducting electricity without resistance. At almost all other angles nothing special happens.","former":["magic angle","magic-angle graphene","magic angle graphene","magic angles","magic-angle"]}},"magnetar":{"kalla":"bc7e7fdd6f","data":{"term":"Magnetar","kort":"A rare kind of neutron star with the strongest magnetic field known in the universe, a thousand times stronger than in ordinary neutron stars. The field is so strong that it cracks the star's crust and drives violent outbursts of radiation.","former":["magnetar","magnetars"]}},"magnetisk-monopol":{"kalla":"d83fd91c41","data":{"term":"Magnetic monopole","kort":"A hypothetical particle that has only one magnetic pole, that is, a north pole without a south pole or vice versa. Theories predict that they might exist, but none has been found.","former":["magnetic monopole","magnetic monopoles","monopole","monopoles","isolated magnetic pole"]}},"magnetisk-rekonnektion":{"kalla":"7e8b19e13f","data":{"term":"Magnetic reconnection","kort":"The process in which magnetic field lines in an electrically conducting gas cloud suddenly break and reconnect in a different direction, so that a large part of the stored magnetic energy becomes heat and motion.","former":["magnetic reconnection","reconnection","reconnection rate","reconnection rates"]}},"magnetiskt-moment":{"kalla":"377b039287","data":{"term":"Magnetic moment","kort":"A measure of how strong a magnet an object or a particle is, and which way it points. Even individual electrons and protons have a magnetic moment, and measuring it is among the most precise things humans can do.","former":["magnetic moment","magnetic moments","magnetic dipole moment","magnetic dipole moments"]}},"magnetometer":{"kalla":"641b08bf1d","data":{"term":"Magnetometer","kort":"An instrument that measures magnetic fields. The most sensitive versions register fields so weak that the Earth's is tens of billions of times stronger.","former":["magnetometer","magnetometers","magnetometry","magnetic field sensor","magnetic field sensors"]}},"magnetsinne":{"kalla":"b9bdbcb1c9","data":{"term":"Magnetic sense","kort":"The ability of animals to sense the Earth's magnetic field and use it to find their way. Which organ does the job has still not been established for any animal.","former":["magnetic sense","magnetic senses","magnetoreception","magnetic compass sense"]}},"magnitud":{"kalla":"d3b0749cf6","data":{"term":"Magnitude","kort":"Astronomers' measure of how bright a celestial object is. The scale is both reversed (lower numbers mean brighter) and logarithmic, so that five magnitudes correspond to a factor of a hundred.","former":["apparent magnitude","apparent magnitudes","absolute magnitude","absolute magnitudes","magnitude scale","stellar magnitude","stellar magnitudes"]}},"magnon":{"kalla":"d7b0d11642","data":{"term":"Magnon","kort":"The smallest portion of a spin wave, that is, of a ripple travelling through a magnetic material. No matter moves in the wave, only the magnetic directions of the atoms.","former":["magnon","magnons","magnonics","magnonic","magnon circuit","magnon circuits","magnon research","magnon dynamics","four-magnon scattering","magnon direction","magnon directions"]}},"masscentrum":{"kalla":"06efba7335","data":{"term":"Centre of mass","kort":"The point where the mass of an object or a system can be thought of as concentrated. The point moves as if all external forces acted right there, however the parts inside are moving.","former":["centre of mass","center of mass","centres of mass","centers of mass","centre-of-mass","center-of-mass","centre of mass theorem","motion of the centre of mass"]}},"materievag":{"kalla":"00738aca76","data":{"term":"Matter wave","kort":"The fact that matter also behaves like a wave. The wavelength gets shorter the greater the momentum, which is why the wave nature is never noticed in everyday objects.","former":["matter wave","matter waves","de broglie wavelength","de broglie wavelengths","de broglie's wavelength","wave-particle duality","wave–particle duality"]}},"matproblemet":{"kalla":"1d81704822","data":{"term":"The measurement problem","kort":"The question of why a measurement gives only a single answer, even though the equation of quantum mechanics describes all possibilities at once. No one agrees on where the transition happens, or what causes it.","former":["the measurement problem","measurement problem","quantum measurement problem"]}},"maxwells-demon":{"kalla":"88956fd6de","data":{"term":"Maxwell's demon","kort":"A thought experiment in which a tiny being sorts fast and slow molecules and so seems to create temperature differences without doing any work. The paradox is resolved by the fact that information costs energy.","former":["maxwell's demon","maxwell demon","maxwell's demons","maxwell demons"]}},"maxwelltid":{"kalla":"8500830aff","data":{"term":"Maxwell time","kort":"The time you have to wait before a material stops behaving like a spring and starts behaving like a viscous liquid. You get it by dividing the viscosity by the stiffness of the material.","former":["maxwell time","maxwell times","maxwell relaxation time","maxwell's relaxation time","relaxation time","relaxation times"]}},"meissnereffekten":{"kalla":"dcfe54e3df","data":{"term":"Meissner effect","kort":"When a superconductor actively pushes the magnetic field out of its interior as it is cooled below its critical temperature. It is the property that makes a magnet float above a cold superconductor.","former":["meissner effect","meissner-ochsenfeld effect","meissner–ochsenfeld effect","meissner effects"]}},"metamaterial":{"kalla":"7f703a865e","data":{"term":"Metamaterial","kort":"Artificial materials built from small, carefully designed building blocks that give properties no natural material has, for example refracting light the “wrong” way.","former":["metamaterial","metamaterials"]}},"meteor":{"kalla":"d5f92da818","data":{"term":"Meteor","kort":"The streak of light from a dust grain burning up high in the atmosphere. The grain itself is called a meteoroid, and whatever might reach the ground is called a meteorite.","former":["meteor","meteors","shooting star","shooting stars","meteor shower","meteor showers","meteor storm","meteor storms"]}},"meteorit":{"kalla":"e4d8ae652b","data":{"term":"Meteorite","kort":"The piece that survives the journey through the atmosphere and reaches the ground. Most meteorites come from the asteroid belt and are older than the Earth itself.","former":["meteorite","meteorites","iron meteorite","iron meteorites","stony meteorite","stony meteorites","chondrite","chondrites"]}},"meteoroid":{"kalla":"268b87e39d","data":{"term":"Meteoroid","kort":"The small body in space that gives rise to a meteor when it hits the atmosphere. Its size ranges from a grain of sand up to a metre or so; larger bodies count as asteroids.","former":["meteoroid","meteoroids","micrometeoroid","micrometeoroids"]}},"mikrogravitation":{"kalla":"6546f4631e","data":{"term":"Microgravity","kort":"The condition on board a spacecraft in orbit, where everything falls in the same direction at the same time and therefore presses against nothing. Gravity is still there and almost as strong as at the ground.","former":["microgravity","weightlessness"]}},"mikrokalorimeter":{"kalla":"aee3ff2b4c","data":{"term":"Microcalorimeter","kort":"A radiation detector that is basically a very small, very cold thermometer: it measures how much warmer a piece of metal becomes when a single photon is absorbed in it.","former":["microcalorimeter","microcalorimeters","transition-edge sensor","transition-edge sensors","transition edge sensor","transition edge sensors"]}},"misslyckad-supernova":{"kalla":"c88673ee32","data":{"term":"Failed supernova","kort":"A heavy star whose core collapses without the envelope being thrown out. Instead of a brilliant explosion the result is a black hole, and in the sky a star is seen simply going out.","former":["failed supernova","failed supernovae","failed supernovas","failed supernova explosion"]}},"moiremonster":{"kalla":"7964d4a4e5","data":{"term":"Moiré pattern","kort":"The new, much larger pattern that appears when two regular patterns are laid on top of each other slightly twisted or with different spacing.","former":["moiré pattern","moiré patterns","moire pattern","moire patterns","moiré","moire"]}},"molekylorbital":{"kalla":"4c96f5cfca","data":{"term":"Molecular orbital","kort":"The region around a molecule where a particular electron is found, described as a wave with both positive and negative parts.","former":["molecular orbital","molecular orbitals"]}},"mork-energi":{"kalla":"f6ca5f75f8","data":{"term":"Dark energy","kort":"The unknown form of energy that makes the expansion of the universe go faster and faster. It makes up about 68 % of the universe's total energy content, and no one knows what it is.","former":["dark energy"]}},"mork-materia":{"kalla":"9d358b22df","data":{"term":"Dark matter","kort":"Invisible matter that neither emits nor absorbs light, but whose gravity holds galaxies together. It seems to weigh about five times more than all ordinary matter.","former":["dark matter"]}},"myografi":{"kalla":"405181b62e","data":{"term":"Muography","kort":"A way of seeing inside large or dense objects, such as pyramids, volcanoes and reactors, by measuring how many muons get through them. It works like an X-ray image, but with muons instead of X-rays.","former":["muography","muon tomography","muon imaging","muon radiography"]}},"myon":{"kalla":"6e2e434264","data":{"term":"Muon","kort":"A heavier relative of the electron, about 207 times as heavy. It lives only a couple of millionths of a second, but constantly rains down on us from cosmic rays: about one per second through an outstretched palm.","former":["muon","muons","cosmic muon","cosmic muons","muon track","muon tracks","antimuon","antimuons","muon beam","muon beams"]}},"myonium":{"kalla":"9d4d762974","data":{"term":"Muonium","kort":"An atom whose nucleus is not an atomic nucleus at all, but a single antiparticle: an antimuon with an ordinary electron around it. It is almost as large as a hydrogen atom, weighs about a ninth as much and survives for only a couple of millionths of a second.","former":["muonium","muonium atom","muonium atoms","muonium beam","muonium beams"]}},"nanoskala":{"kalla":"59e1b421c6","data":{"term":"Nanoscale","kort":"The size range of a few billionths of a metre, where individual atoms and molecules are the building blocks. Well-known materials often get completely new properties when they are shrunk down to this size.","former":["nanoscale","nano-scale","nanometre","nanometres","nanometer","nanometers","nanotechnology","nanostructure","nanostructures","nanoparticle","nanoparticles"]}},"nanotrad":{"kalla":"4a02d23388","data":{"term":"Nanowire","kort":"A crystal that grows like an upright stick, about a hundred nanometres thick and a few micrometres tall. It is so thin that both light and stresses in the material behave differently than in an ordinary block.","former":["nanowire","nanowires","nanotree","nanotrees"]}},"narfalt":{"kalla":"392cd128be","data":{"term":"Near field","kort":"The region closest to an antenna, roughly within a sixth of the wavelength, where the electric and magnetic fields have not yet detached from the antenna as a free wave.","former":["near field","near fields","near-field"]}},"naturlig-linjebredd":{"kalla":"1686f569da","data":{"term":"Natural linewidth","kort":"The fact that a spectral line is never infinitely narrow, but has a width determined by how long the atom's state survives. A short lifetime gives a broad line.","former":["natural linewidth","natural line width","natural linewidths","linewidth","linewidths","line width","line widths"]}},"neutrino":{"kalla":"57ab3c8661","data":{"term":"Neutrino","kort":"The universe's shyest particle: electrically neutral, almost massless and passing straight through the whole Earth without noticing. Every second, tens of billions of neutrinos rush through your thumbnail.","former":["neutrino","neutrinos","antineutrino","antineutrinos","reactor antineutrino","reactor antineutrinos","solar neutrino","solar neutrinos","electron neutrino","electron neutrinos","muon neutrino","muon neutrinos","tau neutrino","tau neutrinos"]}},"neutrinooscillation":{"kalla":"b21c6b9b8a","data":{"term":"Neutrino oscillation","kort":"Neutrinos come in three kinds, and a neutrino sent off as one kind can arrive as another. The change is only possible if neutrinos have mass, which for a long time it was assumed they did not.","former":["neutrino oscillation","neutrino oscillations","flavour change","flavor change","flavour oscillation","flavour oscillations","neutrino flavour","neutrino flavours","neutrino flavor","neutrino flavors"]}},"neutronspridning":{"kalla":"f9865d2fc0","data":{"term":"Neutron scattering","kort":"A method in which a beam of neutrons is sent through a sample and reveals both where the atoms are and how they move, from how the neutrons bounce off.","former":["neutron scattering","neutron instrument","neutron instruments","neutron beam","neutron beams"]}},"neutronstjarna":{"kalla":"20881a110f","data":{"term":"Neutron star","kort":"The compressed core left behind when a heavy star has exploded. It weighs more than the Sun but is only a couple of tens of kilometres across, which makes it the densest object there is short of a black hole.","former":["neutron star","neutron stars"]}},"nova":{"kalla":"802db158f1","data":{"term":"Nova","kort":"An outburst on the surface of a white dwarf that pulls in gas from a neighbour. The star flares up ten-thousandfold but survives, unlike in a supernova.","former":["nova","novae","novas","nova outburst","nova outbursts","helium nova","helium novae"]}},"obestamdhetsrelationen":{"kalla":"dbf49ce84a","data":{"term":"The uncertainty principle","kort":"Heisenberg's rule that position and momentum cannot both be sharply defined at the same time. The better one is known, the fuzzier the other is, and this is not due to the quality of the measuring instruments.","former":["the uncertainty principle","uncertainty principle","heisenberg's uncertainty principle","heisenberg uncertainty principle","uncertainty relation","uncertainty relations","indeterminacy principle"]}},"optimal-styrning":{"kalla":"166edba4e8","data":{"term":"Optimal control","kort":"The branch of mathematics that looks for the very best way of steering a system over time, for example the fastest route to a goal when there are limits on what the control is allowed to do.","former":["optimal control","control theory","optimal control theory","time-optimal","time optimal"]}},"optisk-fiber":{"kalla":"ac595992d0","data":{"term":"Optical fibre","kort":"A hair-thin thread of very pure glass that guides light over long distances by total internal reflection. Optical fibres today carry almost all internet traffic between cities and across the oceans.","former":["optical fibre","optical fibres","optical fiber","optical fibers","fibre optics","fiber optics","fibre-optic","fiber-optic","fibre-optic cable","fibre-optic cables","fiber-optic cable","fiber-optic cables","fibre communication","glass fibre","glass fiber"]}},"optisk-koherenstomografi":{"kalla":"e20e60ee7b","data":{"term":"Optical coherence tomography","kort":"An imaging technique that takes cross-sectional images a few millimetres into tissue using light and interference. It is used daily to examine the retina of the eye.","former":["optical coherence tomography","coherence tomography","oct scan","oct scans"]}},"orbital":{"kalla":"256b80f655","data":{"term":"Orbital","kort":"The region around an atomic nucleus where a particular electron may be found, and the wave function that describes it. The electron has no orbit but exists as a cloud of probability.","former":["atomic orbital","atomic orbitals","orbitals","electron cloud","electron clouds","s orbital","p orbital","d orbital","s-orbital","p-orbital","d-orbital","electron shell","electron shells"]}},"parametrisk-nedkonvertering":{"kalla":"2111486020","data":{"term":"Spontaneous parametric down-conversion","kort":"The process in which a photon passing through a crystal disappears and is replaced by two new photons with the same total energy. It is the most common way of making photons that belong together in pairs.","former":["spontaneous parametric down-conversion","parametric down-conversion","parametric downconversion","down-conversion","downconversion","spdc"]}},"parametrisk-resonans":{"kalla":"56f7bb8e3c","data":{"term":"Parametric resonance","kort":"When an oscillation grows stronger because one of the system's own properties changes in step with the oscillation, instead of an external force pushing it. Pumping a swing is the most common example.","former":["parametric resonance","parametrically driven","parametric pendulum","parametric amplification","parametric oscillation"]}},"parbildning":{"kalla":"cb76fda535","data":{"term":"Pair production","kort":"When energy becomes matter: a sufficiently energetic photon disappears and leaves behind an electron and a positron. It is the most direct illustration that mass and energy are the same thing.","former":["pair production","pair creation","electron–positron pair","electron–positron pairs","electron-positron pair","electron-positron pairs"]}},"parsec":{"kalla":"84f43432b6","data":{"term":"Parsec","kort":"Astronomers' own unit of distance, about 3.26 light years. It is defined from how much a star seems to move in the sky as the Earth moves around the Sun.","former":["parsec","parsecs","kiloparsec","kiloparsecs","megaparsec","megaparsecs","gigaparsec","gigaparsecs"]}},"partikelaccelerator":{"kalla":"906deeca4f","data":{"term":"Particle accelerator","kort":"A machine that drives charged particles up to close to the speed of light with electric fields and steers them with magnets. Used to explore the smallest building blocks of matter, but mostly in healthcare and materials research.","former":["particle accelerator","particle accelerators","storage ring","storage rings","accelerator","accelerators","synchrotron","synchrotrons","synchrotron light","cyclotron","cyclotrons","collision energy","proton synchrotron","synchrocyclotron"]}},"penningfalla":{"kalla":"05952052a6","data":{"term":"Penning trap","kort":"A trap that holds charged particles in the middle of a vacuum using a strong magnetic field and an electric field. Individual ions or electrons can be stored for months and measured with extreme precision.","former":["penning trap","penning traps"]}},"permeabilitet":{"kalla":"d2f1b89e80","data":{"term":"Permeability","kort":"A measure of how easily a material conducts magnetic fields. Iron has a very high permeability and draws the field lines into itself, while air and most other substances hardly affect the field at all.","former":["permeability","magnetic permeability","relative permeability"]}},"permittivitet":{"kalla":"83c749e15e","data":{"term":"Permittivity","kort":"A measure of how much a material weakens an electric field by itself becoming slightly polarised. The same property determines how fast light travels through the material.","former":["permittivity","permittivities","dielectric constant","dielectric constants","relative permittivity","dielectric","dielectrics"]}},"perseiderna":{"kalla":"727692275c","data":{"term":"The Perseids","kort":"The most reliable meteor shower of the year, peaking around 12 August. The dust comes from the comet 109P/Swift–Tuttle.","former":["the perseids","perseids","perseid","perseid meteor shower"]}},"pevatron":{"kalla":"69ddbc7c6e","data":{"term":"PeVatron","kort":"A natural object in space capable of accelerating particles to a million billion electronvolts or more: about a hundred times more powerful than the largest accelerators humans have built.","former":["pevatron","pevatrons","proton pevatron","proton pevatrons"]}},"pikometer":{"kalla":"d26fe843c1","data":{"term":"Picometre","kort":"A trillionth of a metre, the unit of length that suits distances inside an atom and between the atoms in a crystal. There are a thousand picometres in a nanometre.","former":["picometre","picometres","picometer","picometers"]}},"pion":{"kalla":"330f2f93c5","data":{"term":"Pion","kort":"A short-lived particle formed when protons and atomic nuclei collide hard. The neutral version decays almost immediately into two gamma photons, and is therefore the small go-between that reveals where in space protons are being accelerated.","former":["pion","pions","neutral pion","neutral pions","pion decay","pi meson","pi mesons"]}},"plasma":{"kalla":"2cee6e14c6","data":{"term":"Plasma","kort":"The fourth state of matter: a gas so energetic that the electrons have been torn loose from their atoms. Almost all visible matter in the universe, the stars, is plasma.","former":["plasma","plasmas","plasma cloud","plasma clouds"]}},"plasmafrekvens":{"kalla":"599f8ecc7a","data":{"term":"Plasma frequency","kort":"The frequency at which the free electrons in a plasma naturally oscillate. Electromagnetic waves with a lower frequency are reflected by the plasma; waves with a higher frequency pass through.","former":["plasma frequency","plasma frequencies"]}},"plasmon":{"kalla":"e5e45d9ab6","data":{"term":"Plasmon","kort":"A collective surge wave in a material's electrons, counted in portions in the same way as light is counted in photons.","former":["plasmon","plasmons","plasmonic","plasmonics"]}},"pn-overgang":{"kalla":"0633f1977b","data":{"term":"P-n junction","kort":"The junction between an n-doped and a p-doped region in a semiconductor. It lets current through in only one direction and is the basis of diodes, transistors, LEDs and solar cells.","former":["p-n junction","p-n junctions","pn junction","pn junctions","pn-junction","depletion zone","depletion region","depletion layer"]}},"polarisation":{"kalla":"b1b9f5671b","data":{"term":"Polarisation","kort":"The direction in which a light wave's electric field oscillates. Ordinary light oscillates higgledy-piggledy in all directions, but reflections, scattering and magnetic fields can sort out one direction.","former":["polarisation","polarization","polarised","polarized","linearly polarised","linearly polarized","linear polarisation","linear polarization","circular polarisation","circular polarization","circularly polarised","circularly polarized","polarisation direction","polarization direction","degree of polarisation","degree of polarization"]}},"positron":{"kalla":"3d9c761d20","data":{"term":"Positron","kort":"The electron's antiparticle: the same mass, an equally large charge, but positive. It was the first antiparticle to be found, and today it is used every day in hospitals.","former":["positron","positrons","antielectron","antielectrons"]}},"protostjarna":{"kalla":"b04ba8134b","data":{"term":"Protostar","kort":"A star in the making: a dense lump in a collapsing gas cloud that already glows from the heat of compression, but has not yet ignited any nuclear reaction in its centre.","former":["protostar","protostars","protostellar"]}},"pulsar":{"kalla":"f18b2468ea","data":{"term":"Pulsar","kort":"A rotating neutron star whose beam of radiation sweeps past the Earth like the light from a lighthouse. The pulses come so regularly that they can compete with atomic clocks.","former":["pulsar","pulsars","millisecond pulsar","millisecond pulsars","pulsar timing"]}},"qubit":{"kalla":"eb0959b83e","data":{"term":"Qubit","kort":"The memory cell of a quantum computer. Unlike an ordinary bit, which is either zero or one, a qubit can be in a mixture of both, but only until it is read out.","former":["qubit","qubits","quantum bit","quantum bits","logical qubit","logical qubits","physical qubit","physical qubits"]}},"radikalparsmekanismen":{"kalla":"69a5a566b2","data":{"term":"The radical pair mechanism","kort":"The leading chemical explanation for birds' compass. Light creates a pair of molecules each with an unpaired electron, and the Earth's magnetic field controls which product the reaction gives.","former":["the radical pair mechanism","radical pair mechanism","radical pair","radical pairs","cryptochrome","cryptochromes"]}},"radioaktivt-sonderfall":{"kalla":"e2b79cfb92","data":{"term":"Radioactive decay","kort":"Unstable atomic nuclei transform spontaneously and get rid of energy by emitting radiation. When it happens for a single nucleus cannot be predicted, but for a large number of nuclei it follows an exact law.","former":["radioactive decay","radioactivity","radioactive","decay","decays","decayed","decaying"]}},"ramslapning":{"kalla":"d20cd5a5ab","data":{"term":"Frame dragging","kort":"A rotating mass drags the spacetime around it a little way along with its rotation, like a spoon in honey. The effect makes orbits and spinning axes nearby slowly turn in the same direction as the mass rotates.","former":["frame dragging","frame-dragging","lense-thirring effect","lense–thirring effect","gravitomagnetism","gravitomagnetic"]}},"rayleighvag":{"kalla":"45c37d7060","data":{"term":"Rayleigh wave","kort":"A wave that travels along the surface of a solid material and dies away with depth. It sets the upper speed limit for how fast a crack can travel, and it is the most destructive type of wave in an earthquake.","former":["rayleigh wave","rayleigh waves","rayleigh wave speed","surface wave","surface waves"]}},"relativitetsteori":{"kalla":"5829d235e9","data":{"term":"Theory of relativity","kort":"Einstein's two theories of space, time and gravity: the special theory (1905) about what happens near the speed of light, and the general theory (1915), which describes gravity as a curvature of spacetime.","former":["theory of relativity","relativity","special relativity","general relativity","special theory of relativity","general theory of relativity","relativistic","relativistically"]}},"rodforskjutning":{"kalla":"dfa4216ec5","data":{"term":"Redshift","kort":"The stretching of light from a distant object towards longer wavelengths, that is, towards red. It is astronomy's most important measure of how far away, and how far back in time, something lies.","former":["redshift","redshifts","redshifted","red shift","red-shifted","gravitational redshift"]}},"rorelsemangd":{"kalla":"5bd1b9737e","data":{"term":"Momentum","kort":"Mass times velocity. The quantity describes how hard something is to stop, and in a system unaffected by anything outside it can only be moved between the parts, never disappear.","former":["momentum","momenta","linear momentum","conservation of momentum"]}},"rorelsemangdsmoment":{"kalla":"8a873b4204","data":{"term":"Angular momentum","kort":"A measure of how much rotation a system contains: mass, speed and distance from the axis of rotation multiplied together. The quantity cannot disappear, only be moved somewhere else.","former":["angular momentum","angular momenta","conservation of angular momentum"]}},"rotationsbarriaren":{"kalla":"9084c97a8e","data":{"term":"The spin barrier","kort":"The limit of about one rotation per 2.2 hours that asteroids larger than about 150 metres almost never spin faster than. If a loose rubble pile spins faster, it is torn apart.","former":["the spin barrier","spin barrier","spin barriers","rotation barrier","spin-rate barrier","spin rate barrier"]}},"rotationskurva":{"kalla":"7f194a42c3","data":{"term":"Rotation curve","kort":"A graph of how fast the stars in a galaxy move, plotted against their distance from the galaxy's centre. That the curves are flat is the classic reason for believing in dark matter.","former":["rotation curve","rotation curves","galaxy rotation","galactic rotation","flat rotation curve","flat rotation curves","galaxy rotation curve","galaxy rotation curves"]}},"rumtid":{"kalla":"38761e08f6","data":{"term":"Spacetime","kort":"The three directions of space and time joined into a single four-dimensional fabric. In the general theory of relativity, gravity is nothing other than the fabric being curved.","former":["spacetime","space-time","spacetime geometry","spacetime curvature","curvature of spacetime","spacetime diagram","spacetime diagrams","four-dimensional spacetime"]}},"rymdvader":{"kalla":"8c9fb158dc","data":{"term":"Space weather","kort":"A collective name for the changing conditions in space around the Earth, driven by the Sun: bursts of radiation, showers of particles and clouds of gas that disturb satellites, radio and power grids.","former":["space weather","space weather event","space weather events","magnetic storm","magnetic storms","geomagnetic storm","geomagnetic storms"]}},"sagnaceffekten":{"kalla":"5509c63610","data":{"term":"Sagnac effect","kort":"When light or other waves are sent both ways around a rotating ring, they arrive at different times. The difference reveals how fast the ring is turning.","former":["sagnac effect","sagnac phase","ring laser","ring lasers","ring laser gyroscope","ring laser gyroscopes","ring-laser gyroscope"]}},"scintillator":{"kalla":"2e0faf55a8","data":{"term":"Scintillator","kort":"A substance that gives a small flash of light every time a particle passes through it. By measuring the flashes you can count particles that are otherwise completely invisible.","former":["scintillator","scintillators","scintillator liquid","liquid scintillator","liquid scintillators","scintillation"]}},"skottbrus":{"kalla":"229311a247","data":{"term":"Shot noise","kort":"The unavoidable jitter in every measurement that counts particles one by one. If you count a certain number on average, the result varies by roughly the square root of that number.","former":["shot noise","photon noise","counting statistics","poisson noise"]}},"skottsekund":{"kalla":"cf3075d26f","data":{"term":"Leap second","kort":"An extra second inserted into the world's official time so that clocks do not run ahead of the Earth's rotation. Since 1972, 27 of them have been inserted.","former":["leap second","leap seconds"]}},"skyrmion":{"kalla":"43af136b48","data":{"term":"Skyrmion","kort":"A small, knot-like swirl in a field (for example in a material's magnetisation) that is surprisingly stable and can be moved around like a particle.","former":["skyrmion","skyrmions"]}},"solmassa":{"kalla":"6ca4039574","data":{"term":"Solar mass","kort":"The mass of our Sun, about 330 000 times that of the Earth. It is used as a yardstick when giving the masses of stars, black holes and entire galaxies.","former":["solar mass","solar masses"]}},"solsynkron-bana":{"kalla":"7ac6d552f9","data":{"term":"Sun-synchronous orbit","kort":"A satellite orbit arranged so that the satellite passes over each place on Earth at the same local time every day. The shadows in the images are then the same from one time to the next.","former":["sun-synchronous orbit","sun-synchronous orbits","sun synchronous orbit","sun synchronous orbits","sun-synchronous"]}},"speckle":{"kalla":"fee090a79c","data":{"term":"Speckle","kort":"The grainy pattern of bright and dark dots that appears when laser light is scattered from an uneven surface. The dots are a random interference pattern.","former":["speckle","speckles","speckle pattern","speckle patterns","speckle noise","laser speckle"]}},"spektrometer":{"kalla":"a8253602bb","data":{"term":"Spectrometer","kort":"The instrument that splits light by wavelength and measures how much there is of each. It is with a spectrometer that a spectrum is recorded.","former":["spectrometer","spectrometers","spectrograph","spectrographs","spectroscope","spectroscopes"]}},"spektroskopi":{"kalla":"18c7c5058c","data":{"term":"Spectroscopy","kort":"The art of splitting light by wavelength and reading the pattern of bright and dark lines. Since every element has its own pattern of lines, you can work out what something is made of without touching it.","former":["spectroscopy","spectroscopic","spectroscopically","laser spectroscopy","photoelectron spectroscopy","gamma spectroscopy","gamma-ray spectroscopy","terahertz spectroscopy"]}},"spektrum":{"kalla":"819e54ecd6","data":{"term":"Spectrum","kort":"Light split up by wavelength, like a rainbow with bright or dark lines in it. The pattern of lines is an element's fingerprint and reveals what the source is made of.","former":["spectrum","spectra","spectrums","emission spectrum","emission spectra","absorption spectrum","absorption spectra","line spectrum","continuous spectrum","spectral line","spectral lines"]}},"spinn":{"kalla":"e4957f796e","data":{"term":"Spin","kort":"A built-in quantum property of particles that makes them behave like tiny magnets and carry their own angular momentum, even though nothing is actually spinning.","former":["spin","electron spin","electron spins","nuclear spin","nuclear spins"]}},"spinntronik":{"kalla":"1e6b2e3cd8","data":{"term":"Spintronics","kort":"Electronics that uses the electron's spin instead of just its charge. The technology gave us dense hard disks and is used today for memories that keep their contents without power.","former":["spintronics","spintronic","spin electronics","spin current","spin currents","giant magnetoresistance"]}},"spinnvag":{"kalla":"352d2c2085","data":{"term":"Spin wave","kort":"A ripple that travels through a magnetic material without any atom moving. What travels is the magnetic direction of the atoms, which wobbles round in step with that of their neighbours, slightly shifted from atom to atom.","former":["spin wave","spin waves","spin-wave mode","spin-wave modes","spin wave mode","spin wave modes"]}},"squid":{"kalla":"bdca2a9869","data":{"term":"SQUID","kort":"A magnetic field meter built from a superconducting ring: for decades the most sensitive there was, but it has to be kept cooled to a few degrees above absolute zero.","former":["squid","squids","squid magnetometer","squid magnetometers","superconducting quantum interference device","superconducting quantum interference devices"]}},"standardkvantgransen":{"kalla":"bdb336530f","data":{"term":"The standard quantum limit","kort":"The noise limit that applies when each particle in a measurement is counted separately: the precision only improves as the square root of the number of measurements. With entangled probes, the limit can be pushed past.","former":["the standard quantum limit","standard quantum limit","standard quantum limits","heisenberg scaling","heisenberg limit"]}},"standardmodellen":{"kalla":"93782d917e","data":{"term":"The Standard Model","kort":"The basic map of particle physics: a list of the smallest building blocks of matter and the particles that carry the forces between them. It describes three of nature's four forces; gravity is left out.","former":["the standard model","standard model","elementary particle","elementary particles"]}},"stark-vaxelverkan":{"kalla":"8031759f91","data":{"term":"Strong interaction","kort":"The force that holds the quarks together inside protons and neutrons, and that in turn holds the atomic nucleus together. It is the strongest of nature's four forces but reaches only a few nuclear diameters.","former":["strong interaction","strong force","strong nuclear force","colour charge","color charge","colour charges","color charges","quantum chromodynamics","qcd","gluon field","gluon fields"]}},"steril-neutrino":{"kalla":"2dceb92c44","data":{"term":"Sterile neutrino","kort":"A hypothetical fourth kind of neutrino that is not affected by any of nature's forces except gravity. It has been proposed to explain several measurements in which neutrinos seem to disappear, but has never been found.","former":["sterile neutrino","sterile neutrinos"]}},"stern-gerlach-forsoket":{"kalla":"4abc908906","data":{"term":"The Stern–Gerlach experiment","kort":"The experiment from 1922 in which a beam of silver atoms was split in two as it passed through an uneven magnetic field. It showed that the magnetic moments of atoms can only point in certain definite directions.","former":["the stern–gerlach experiment","stern–gerlach experiment","stern-gerlach experiment","the stern-gerlach experiment","stern–gerlach","stern-gerlach"]}},"straldos":{"kalla":"d99a5282b6","data":{"term":"Radiation dose","kort":"A measure of how much energy ionising radiation leaves behind in a material or a body. It is the dose, not the strength of the radiation source itself, that determines the damage.","former":["radiation dose","radiation doses","absorbed dose","absorbed doses","equivalent dose","equivalent doses"]}},"straljet":{"kalla":"519506528c","data":{"term":"Jet stream","kort":"A narrow band in an atmosphere where the wind blows much faster than in the surrounding air. On Earth jet streams steer the weather, and on the gas planets they draw the bands seen in telescopes.","former":["jet stream","jet streams","jetstream","jetstreams"]}},"stromskikt":{"kalla":"58c550c5bf","data":{"term":"Current sheet","kort":"A thin layer in a plasma in which a strong electric current flows, because the magnetic field points in opposite directions on the two sides of the layer.","former":["current sheet","current sheets"]}},"subduktion":{"kalla":"8c4485faef","data":{"term":"Subduction","kort":"When one of the Earth's tectonic plates slides down beneath another and sinks into the mantle. Deep ocean trenches, volcanic chains and the most powerful earthquakes form there.","former":["subduction","subduction zone","subduction zones","subduct","subducts","subducted","subducting"]}},"summafrekvensgenerering":{"kalla":"ffccfb32f2","data":{"term":"Sum-frequency generation","kort":"A method in which two laser beams with different frequencies meet and create light whose frequency is the sum of the two. Since this only happens at a boundary, the method is used to study the very outermost molecules on a surface.","former":["sum-frequency generation","sum frequency generation","sum-frequency","sum frequency","sfg","sum-frequency spectroscopy"]}},"superfluid":{"kalla":"99fbffcedc","data":{"term":"Superfluid","kort":"A liquid that flows completely without internal friction. It can creep up the walls of its container and flow through pores so small that no ordinary liquid can get through.","former":["superfluid","superfluids","superfluidity"]}},"superhydrid":{"kalla":"2c7c7a7493","data":{"term":"Superhydride","kort":"A substance in which metal atoms sit enclosed in cages of hydrogen atoms, made under extreme pressure. Several superhydrides conduct electricity completely without resistance at temperatures that are high by superconductivity standards.","former":["superhydride","superhydrides","hydride","hydrides","metal hydride","metal hydrides"]}},"superjonisk-is":{"kalla":"38dc0c87b1","data":{"term":"Superionic ice","kort":"A state of water under very high pressure and high temperature, in which the oxygen atoms stay in a solid crystal lattice while the hydrogen nuclei move freely between them. The substance is therefore solid and liquid at the same time, depending on which kind of atom you look at.","former":["superionic ice","superionic","superionic water","superionic conductor","superionic conductors"]}},"superjord":{"kalla":"af0dab6bc4","data":{"term":"Super-Earth","kort":"A rocky planet that is heavier than the Earth but lighter than Neptune. Such planets are the most common ones we know of, even though there is not a single one in our own solar system.","former":["super-earth","super-earths","super earth","super earths"]}},"supernova":{"kalla":"603be60977","data":{"term":"Supernova","kort":"A stellar explosion that for a few weeks can shine as brightly as an entire galaxy. Behind the name lie two completely different ways for a star to blow up.","former":["supernova","supernovae","supernovas","supernova explosion","supernova explosions","supernova remnant","supernova remnants","core-collapse supernova","core-collapse supernovae"]}},"superposition":{"kalla":"718f52ef13","data":{"term":"Superposition","kort":"When a quantum system is in several possibilities at once, not in one of them that we happen to lack information about. In a measurement the state collapses into a single answer.","former":["superposition","superpositions","superposition state","superposition states","superposed"]}},"supraledare":{"kalla":"344e62d4c8","data":{"term":"Superconductor","kort":"A material that below a certain critical temperature conducts electricity completely without electrical resistance, and also pushes magnetic fields out of its interior, so that magnets can float above it.","former":["superconductor","superconductors","superconductivity","superconducting","cuprate superconductor","cuprate superconductors","cuprates"]}},"svag-vaxelverkan":{"kalla":"37a70fb85d","data":{"term":"Weak interaction","kort":"The only force of nature that can change a quark from one type to another. It lies behind beta decay and therefore behind a large part of the radioactivity around us.","former":["weak interaction","weak force","weak nuclear force","semileptonic decay","semileptonic decays"]}},"svart-hal":{"kalla":"153c1a28de","data":{"term":"Black hole","kort":"A region where so much mass has been packed into so small a space that nothing can get away from it, not even light. The boundary is called the event horizon.","former":["black hole","black holes","supermassive black hole","supermassive black holes"]}},"svartkroppsstralning":{"kalla":"754b714e73","data":{"term":"Black-body radiation","kort":"The light that everything emits simply because it has a temperature. The distribution of colours depends only on how hot the object is, not on what it is made of.","former":["black-body radiation","blackbody radiation","black body radiation","thermal radiation","black body","black-body","blackbody","black bodies","blackbodies"]}},"terahertzstralning":{"kalla":"2d672709db","data":{"term":"Terahertz radiation","kort":"Electromagnetic waves in the borderland between microwaves and infrared light: for a long time so hard both to create and to catch that the region was called the “terahertz gap”.","former":["terahertz radiation","terahertz range","terahertz waves","terahertz light","terahertz gap","terahertz band","terahertz bands","terahertz"]}},"termiskt-brus":{"kalla":"3090ee68a4","data":{"term":"Thermal noise","kort":"The random voltage that arises across every conductor simply because it is warm. It sets a lower limit for how weak signals an instrument can perceive at all.","former":["thermal noise","johnson noise","johnson-nyquist noise","johnson–nyquist noise","nyquist noise"]}},"termoelektrisk-effekt":{"kalla":"671e59e3aa","data":{"term":"Thermoelectric effect","kort":"A temperature difference across a material gives rise to an electrical voltage, and conversely a current can pump heat, so that one side becomes cold and the other warm.","former":["thermoelectric effect","thermoelectric effects","thermoelectric","thermoelectricity","seebeck effect","peltier effect","peltier element","peltier elements","thermocouple","thermocouples"]}},"thomsonspridning":{"kalla":"6a685beb1e","data":{"term":"Thomson scattering","kort":"When light bounces off free electrons without changing its energy. Since the electrons' motion shifts the colour of the scattered light, the method can be used as a thermometer for plasma.","former":["thomson scattering","thomson scattering measurement","thomson scattering measurements"]}},"tidsdilatation":{"kalla":"4fef024c43","data":{"term":"Time dilation","kort":"The fact that time passes more slowly in a system rushing past at high speed, and more slowly where gravity is strong. The effect has been measured with clocks and has to be taken into account in satellite navigation.","former":["time dilation","time dilations","gravitational time dilation"]}},"tidskristall":{"kalla":"f67a498d1b","data":{"term":"Time crystal","kort":"A phase of matter that repeats itself in time instead of in space: the system ticks by itself in a stable rhythm, like a crystal whose pattern lies in time.","former":["time crystal","time crystals"]}},"tjerenkovstralning":{"kalla":"d730809fed","data":{"term":"Cherenkov radiation","kort":"A faint blue light that arises when a charged particle moves faster than light does in the same material, for example in water or ice.","former":["cherenkov radiation","cherenkov light","cerenkov radiation","čerenkov radiation","cherenkov effect"]}},"topologiskt-skydd":{"kalla":"448a6db4eb","data":{"term":"Topological protection","kort":"When a property is determined by an overall shape rather than by the details, it becomes almost impossible to destroy, like the knot in a rope that stays however much you pull and twist.","former":["topological protection","topologically protected","topological","topology","topological insulator","topological insulators","edge state","edge states"]}},"totalreflektion":{"kalla":"3c90b793cc","data":{"term":"Total internal reflection","kort":"When light trying to leave a dense material for a less dense one is thrown completely back, if it hits the surface at too shallow an angle. The boundary between getting out and bouncing is called the critical angle.","former":["total internal reflection","total reflection","critical angle","critical angles"]}},"tritium":{"kalla":"93bfbb50f2","data":{"term":"Tritium","kort":"The heaviest hydrogen isotope, with two neutrons in its nucleus. It is radioactive with a half-life of just over twelve years and is used in fusion research and in self-luminous signs.","former":["tritium","triton","tritons","tritium nucleus","tritium nuclei"]}},"troghetsmoment":{"kalla":"b051fd6692","data":{"term":"Moment of inertia","kort":"A measure of how hard it is to set something rotating or to make it stop spinning. It depends not only on how heavy the object is, but on how far from the axis of rotation its mass is.","former":["moment of inertia","moments of inertia","rotational inertia"]}},"tunneleffekt":{"kalla":"87143d68c8","data":{"term":"Tunnelling","kort":"A quantum phenomenon in which a particle gets through a barrier that, according to classical physics, it does not have enough energy to get over. It is tunnelling that makes the Sun shine.","former":["tunnelling","tunneling","quantum tunnelling","quantum tunneling","tunnel effect","tunnelling probability","tunneling probability","tunnelled","tunneled"]}},"turbulens":{"kalla":"7cddae9e9a","data":{"term":"Turbulence","kort":"The swirling, chaotic state a gas or liquid enters when the flow becomes fast enough. The motion obeys known laws but still cannot be predicted in detail.","former":["turbulence","turbulent","turbulent flow","laminar","laminar flow","quantum turbulence"]}},"ultrahogvakuum":{"kalla":"2b67185e27","data":{"term":"Ultra-high vacuum","kort":"A vacuum so empty that only a vanishingly small remnant of gas is left: the air around us is roughly a thousand trillion times denser, or more. It is needed whenever individual atoms or particles are to be left undisturbed, since a single collision can ruin the experiment.","former":["ultra-high vacuum","ultrahigh vacuum","ultra high vacuum","extreme high vacuum","high vacuum"]}},"underkylning":{"kalla":"95ee2f9690","data":{"term":"Supercooling","kort":"When a liquid is kept in liquid form below its own freezing point. The state is unstable: the slightest disturbance can make the whole liquid freeze in an instant.","former":["supercooling","supercooled","supercooled water","undercooling","undercooled"]}},"undulator":{"kalla":"735252ac2b","data":{"term":"Undulator","kort":"A long row of magnets of alternating direction that forces a beam of fast electrons to weave its way along. Every turn makes the electrons emit radiation, usually X-rays.","former":["undulator","undulators"]}},"uppkonvertering":{"kalla":"c5422f8fb2","data":{"term":"Upconversion","kort":"Turning light with low photon energy into light with higher photon energy, for example infrared into visible. The extra energy always has to come from somewhere.","former":["upconversion","up-conversion","upconvert","upconverts","upconverted","upconverter","upconverters"]}},"utspadningskryostat":{"kalla":"9da1abd92e","data":{"term":"Dilution refrigerator","kort":"A cooling machine that reaches temperatures of about a hundredth of a degree above absolute zero by mixing two kinds of helium. Used for quantum computers and superconductors.","former":["dilution refrigerator","dilution refrigerators","dilution cryostat","dilution cryostats","dilution fridge","dilution fridges"]}},"vagfunktion":{"kalla":"807d274a9d","data":{"term":"Wave function","kort":"The mathematical wave that describes a particle in quantum mechanics. The square of its magnitude tells you how likely it is to find the particle in a particular place.","former":["wave function","wave functions","wavefunction","wavefunctions"]}},"vaglangd":{"kalla":"1b6d980f67","data":{"term":"Wavelength","kort":"The distance between two neighbouring wave crests. For light, the wavelength determines the colour, and together with the speed of light it determines the frequency.","former":["wavelength","wavelengths","wave length","wave lengths"]}},"vagtal":{"kalla":"515793e9b8","data":{"term":"Wavenumber","kort":"A measure of how many waves fit into a given distance. If the wave goes round a circle, the wavenumber must be a whole number, otherwise the wave does not meet itself properly after one turn.","former":["wavenumber","wavenumbers","wave number","wave numbers"]}},"vagturbulens":{"kalla":"0d635d802d","data":{"term":"Wave turbulence","kort":"A swarm of waves of different sizes that pass energy on to each other, from the largest down to the smallest, where the energy becomes heat.","former":["wave turbulence","wave cascade","wave cascades"]}},"vakuumdubbelbrytning":{"kalla":"492eb56e52","data":{"term":"Vacuum birefringence","kort":"The prediction of quantum physics that a very strong magnetic field turns empty space into an optical material that refracts light by different amounts depending on how the light wave oscillates. The effect was predicted in 1936 and has never been produced in a laboratory.","former":["vacuum birefringence","critical field strength","vacuum resonance","schwinger limit"]}},"vakuumfluktuation":{"kalla":"2d3795089c","data":{"term":"Vacuum fluctuation","kort":"The trembling that remains in an electromagnetic field even when all energy has been removed. Empty space is therefore never completely still, and the trembling has measurable effects on atoms and materials.","former":["vacuum fluctuation","vacuum fluctuations","zero-point fluctuation","zero-point fluctuations","zero-point oscillation","zero-point oscillations","quantum vacuum","virtual particle","virtual particles","virtual photon","virtual photons"]}},"vakuumultraviolett":{"kalla":"aeeb856047","data":{"term":"Vacuum ultraviolet","kort":"Ultraviolet light with such a short wavelength, roughly 100 to 200 nanometres, that it is absorbed by air. It can therefore only travel in a vacuum or in a gas that lets it through.","former":["vacuum ultraviolet","vacuum-ultraviolet","vacuum ultraviolet light","vacuum ultraviolet radiation","vuv","vuv light","vuv radiation","vuv laser","vuv lasers"]}},"vatebindning":{"kalla":"5da66bebd4","data":{"term":"Hydrogen bond","kort":"A weak attraction between a hydrogen atom in one molecule and an oxygen, nitrogen or fluorine atom in another. Hydrogen bonds hold water together and explain why it only boils at 100 °C.","former":["hydrogen bond","hydrogen bonds","hydrogen bonding"]}},"vintergatan":{"kalla":"66d67d552f","data":{"term":"The Milky Way","kort":"Our own galaxy: a barred spiral with hundreds of billions of stars, about 100 000 light years across. The bright band in the night sky is its disc seen from inside.","former":["the milky way","milky way","milky way galaxy","our galaxy"]}},"viskoelasticitet":{"kalla":"af718cc8ce","data":{"term":"Viscoelasticity","kort":"When a material behaves like a mixture of a spring and a viscous liquid, so that its response depends on how fast and for how long it is loaded.","former":["viscoelasticity","viscoelastic","stress relaxation"]}},"viskositet":{"kalla":"340270e14f","data":{"term":"Viscosity","kort":"A measure of how sluggishly a substance flows: how strongly it resists when the layers inside it have to slide past each other. Water has a low viscosity, honey a high one and rock the highest of all.","former":["viscosity","viscosities","viscosity value","viscosity values","viscosity limit","viscosity range","pascal second","pascal seconds","pascal-second","pascal-seconds"]}},"vit-dvarg":{"kalla":"09e29added","data":{"term":"White dwarf","kort":"The burnt-out core left behind when a star the size of the Sun dies: about as large as the Earth but as heavy as a star.","former":["white dwarf","white dwarfs","white dwarves","white dwarf star","white dwarf stars"]}},"wimp":{"kalla":"2040153a46","data":{"term":"WIMP","kort":"One of the most studied candidates for what dark matter is made of: a heavy particle that hardly cares about ordinary matter, but that can still knock into an atomic nucleus on rare occasions.","former":["wimp","wimps","wimp search","wimp searches","weakly interacting massive particle","weakly interacting massive particles"]}},"yorp-effekten":{"kalla":"357333f508","data":{"term":"YORP effect","kort":"A small twisting action from sunlight that over millions of years can make small asteroids spin faster or slower.","former":["yorp effect","the yorp effect","yorp"]}},"ytljusstyrka":{"kalla":"5d3ae45146","data":{"term":"Surface brightness","kort":"How much light an extended object emits per unit area of sky, usually given in magnitudes per square arcsecond. Low surface brightness means hard to photograph.","former":["surface brightness","surface brightnesses","low surface brightness"]}},"yttriumjarngranat":{"kalla":"80ada172a4","data":{"term":"Yttrium iron garnet","kort":"A transparent magnetic mineral that damps magnetic oscillations less than any other known material. That is why it is used in almost all experiments with spin waves.","former":["yttrium iron garnet","yttrium iron garnets","iron garnet","iron garnets","yig"]}}});
